window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc01"]={"id":"bc01","title":"1. 生命的分子基础","sub":"朱圣庚《生物化学》第4版 · 第1章","sub2":"第1章 · 94页原书版课件 + 章节测试","modules":[{"i":0,"name":"第1章 原书版课件（81页）","slides":[{"i":0,"sec":"第1章 原书版课件","title":"生命的分子基础","notes":"本章学习入口：先建立“生命属性→生物分子→结构/非共价作用→水/细胞→起源进化”的主线。","img":"assets/img/bc01deck/slide-01.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第01页","imageExplain":"这张图在讲：本章学习入口：先建立“生命属性→生物分子→结构/非共价作用→水/细胞→起源进化”的主线。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":1,"sec":"第1章 原书版课件","title":"第1章 生命的分子基础 · 8 节 33 个子节","notes":"先用学习地图建立全章框架。第1章不是零散概念，而是从生命属性出发，依次回答生命物质是什么、如何形成三维结构、靠什么作用稳定、水与细胞的意义，最后落到生命起源。","img":"assets/img/bc01deck/slide-02.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第02页","imageExplain":"这张图在讲：先用学习地图建立全章框架。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":2,"sec":"第1章 原书版课件","title":"生命属性与生物化学","notes":"本节导览：生命属性可以归纳为哪三个方面？；为什么说生物分子既复杂又同一？；自复制与自装配为什么是生命的精华？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-03.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第03页","imageExplain":"这张图在讲：本节导览：生命属性可以归纳为哪三个方面？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":3,"sec":"第1章 原书版课件","title":"（一）化学成分复杂而同一、结构错综而有序","notes":"这一页是本章的总纲。强调“复杂”指种类多、结构精细；“同一”指所有生物都用相似的生物分子和同一套构建逻辑。结构层次要能顺背，并区分共价键与非共价作用分别负责哪一层。","img":"assets/img/bc01deck/slide-04.jpg?v=20261108eg","points":["细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。","蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。","生物界化学成分高度复杂，但结构模式和功能高度同一。","结构层次：单体亚基 → 大分子 → 超分子复合体 → 细胞器 → 细胞。"],"check":{"kind":"short","id":"bc01_s4_check","q":"本页「（一）化学成分复杂而同一、结构错综而有序」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。；蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。；生物界化学成分高度复杂，但结构模式和功能高度同一。；结构层次：单体亚基 → 大分子 → 超分子复合体 → 细胞器 → 细胞。","e":"解析：这一页是本章的总纲。强调“复杂”指种类多、结构精细；“同一”指所有生物都用相似的生物分子和同一套构建逻辑。结构层次要能顺背，并区分共价键与非共价作用分别负责哪一层。 关键点：细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。；蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。；生物界化学成分高度复杂，但结构模式和功能高度同一。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s4_exam_clean","q":"本页强调生物界化学成分的什么特点？","o":["A. 化学成分复杂，但结构模式和构建逻辑高度同一","B. 所有生物化学成分完全相同","C. 生物分子都没有结构层次","D. 只有无机分子参与生命活动"],"a":"A","e":"“复杂”指种类多、结构精细；“同一”指都用相似的生物分子和同一套构建逻辑。","oe":["正确。","错：种类和结构并不完全相同。","错：存在单体→大分子→超分子→细胞器等层次。","错：蛋白质、核酸、糖、脂等有机分子也参与。"],"src":"期末·选择题"},"source":"老师第1章PPT 第04页","imageExplain":"这张图在讲：强调“复杂”指种类多、结构精细。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。；蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。。","srcType":"原书","role":"查阅"},{"i":4,"sec":"第1章 原书版课件","title":"（二）利用环境的能量和物质进行自我更新","notes":"用“开放系统”解释生命为什么能维持有序：不是违背热力学第二定律，而是把熵增转移到环境中。强调ATP是通用能量货币，NADPH主要提供还原力。","img":"assets/img/bc01deck/slide-05.jpg?v=20261108eg","points":["新陈代谢=合成代谢（同化）+分解代谢（异化）。","代谢途径：上一步产物是下一步底物，每一步由专一酶催化。","分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。","生物是开放系统：摄取低熵高能物质，排出低能高熵产物。"],"check":{"kind":"short","id":"bc01_s5_check","q":"本页「（二）利用环境的能量和物质进行自我更新」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：新陈代谢=合成代谢（同化）+分解代谢（异化）。；代谢途径：上一步产物是下一步底物，每一步由专一酶催化。；分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。；生物是开放系统：摄取低熵高能物质，排出低能高熵产物。","e":"解析：用“开放系统”解释生命为什么能维持有序：不是违背热力学第二定律，而是把熵增转移到环境中。强调ATP是通用能量货币，NADPH主要提供还原力。 关键点：新陈代谢=合成代谢（同化）+分解代谢（异化）。；代谢途径：上一步产物是下一步底物，每一步由专一酶催化。；分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s5_exam","q":"关于本页「（二）利用环境的能量和物质进行自我更新」，下列哪项表述正确？","o":["A. 新陈代谢=合成代谢（同化）+分解代谢（异化）。","B. 同一构型可用 Fischer 投影式、透视式、立体模型表示。","C. 强度受介电常数、离子强度和环境 pH 影响。","D. C：水分子通过氢键连成三维网络，可看出六元环排列。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：新陈代谢=合成代谢（同化）+分解代谢（异化）。","属于「图1-5 甘油醛的构型（D/L 命名系统）」的内容，不是本页核心。","属于「（一）离子相互作用」的内容，不是本页核心。","属于「图1-12 水分子结构与冰中氢键」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第05页","imageExplain":"这张图在讲：用“开放系统”解释生命为什么能维持有序：不是违背热力学第二定律，而是把熵增转移到环境中。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：新陈代谢=合成代谢（同化）+分解代谢（异化）。；代谢途径：上一步产物是下一步底物，每一步由专一酶催化。。","srcType":"原书","role":"查阅"},{"i":5,"sec":"第1章 原书版课件","title":"（三）自我复制和自我装配是生命状态的精华","notes":"这一页把“遗传”与“自装配”放在一起：前者保证世代之间信息连续，后者保证分子自动形成有序结构。中心法则只讲信息流，不要把它误解为所有信息都只从DNA单向流动。","img":"assets/img/bc01deck/slide-06.jpg?v=20261108eg","points":["DNA是主要遗传物质：信息量大、稳定、可忠实复制。","DNA半保留复制；突变与重组是变异和进化的分子基础。","遗传信息表达：DNA→RNA→蛋白质；三联体密码决定氨基酸。","自装配：亚基自发缔合成复合体，驱动力主要是疏水作用。"],"check":{"kind":"short","id":"bc01_s6_check","q":"本页「（三）自我复制和自我装配是生命状态的精华」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：DNA是主要遗传物质：信息量大、稳定、可忠实复制。；DNA半保留复制；突变与重组是变异和进化的分子基础。；遗传信息表达：DNA→RNA→蛋白质；三联体密码决定氨基酸。；自装配：亚基自发缔合成复合体，驱动力主要是疏水作用。","e":"解析：这一页把“遗传”与“自装配”放在一起：前者保证世代之间信息连续，后者保证分子自动形成有序结构。中心法则只讲信息流，不要把它误解为所有信息都只从DNA单向流动。 关键点：DNA是主要遗传物质：信息量大、稳定、可忠实复制。；DNA半保留复制；突变与重组是变异和进化的分子基础。；遗传信息表达：DNA→RNA→蛋白质；三联体密码决定氨基酸。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s6_exam","q":"关于本页「（三）自我复制和自我装配是生命状态的精华」，下列哪项表述正确？","o":["A. 结合位点的形状、电荷和氢键供受体必须互补。","B. DNA是主要遗传物质：信息量大、稳定、可忠实复制。","C. 四类非共价作用：离子相互作用、氢键、范德华力、疏水作用。","D. pH = pKa + lg([A⁻]/[HA])；[A⁻]=盐，[HA]=酸。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（六）生物分子间的相互作用是立体专一的」的内容，不是本页核心。","本页要点：DNA是主要遗传物质：信息量大、稳定、可忠实复制。","属于「第5节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「第6节难点：缓冲液计算三步走」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第06页","imageExplain":"这张图在讲：这一页把“遗传”与“自装配”放在一起：前者保证世代之间信息连续，后者保证分子自动形成有序结构。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：DNA是主要遗传物质：信息量大、稳定、可忠实复制。；DNA半保留复制；突变与重组是变异和进化的分子基础。。","srcType":"原书","role":"查阅"},{"i":6,"sec":"第1章 原书版课件","title":"第1节 · 3句话 + 2题自测","notes":"第1节收束：用三句话把生命属性、结构层次、能量与信息串起来。","img":"","points":["生命属性可归纳为化学成分复杂而同一、结构有序、自我更新、自我复制与自装配。","单体通过共价键聚合成生物大分子，更高层次靠非共价作用组装。","生命是开放系统：靠能量流维持有序，靠 DNA 复制与表达延续遗传信息。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap1_1","kind":"mcq","q":"生命属性通常不包括下列哪项？","o":["A. 化学成分复杂而同一","B. 利用环境物质和能量自我更新","C. 自我复制与自我装配","D. 无限生长且不死亡"],"a":"D","e":"生命属性包括前三项；个体不能无限生存，生命通过繁殖延续。","oe":["属于生命属性。","属于生命属性。","属于生命属性。","“无限生长且不死亡”不是生命属性。"],"src":"本节收束"},{"id":"bc01_wrap1_2","kind":"mcq","q":"自装配的主要驱动力通常是？","o":["A. 共价键","B. 疏水作用（熵驱动）","C. 离子键","D. 二硫键"],"a":"B","e":"自装配由疏水作用等非共价作用驱动，结果是自由能降低。","oe":["共价键主要负责聚合。","疏水作用是主要驱动力。","离子键只是非共价作用之一。","二硫键是共价交联。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":7,"sec":"第1章 原书版课件","title":"第1节难点：生命属性怎么答？","notes":"第1节难点：把生命属性从三个层面拆开，每层配一个分子例子。","img":"","points":["① 化学成分与结构有序；② 能量与物质自我更新；③ 自我复制与自我装配。","生命是开放系统，靠能量流维持低熵有序。","DNA复制保证信息连续；蛋白质执行功能；自装配形成结构。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break8","kind":"short","q":"请用3步回答“生命属性”，并举一个分子例子。","a":"得分点：①化学成分与结构有序；②能量与物质自我更新；③自我复制与自我装配；例：DNA复制/核糖体自装配。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":8,"sec":"第1章 原书版课件","title":"生物化学与分子生物学","notes":"本节导览：生物化学经历哪三个阶段？；分子生物学与生物化学是什么关系？；中国生物化学有哪些重要贡献？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-09.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第09页","imageExplain":"这张图在讲：本节导览：生物化学经历哪三个阶段？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":9,"sec":"第1章 原书版课件","title":"（一）现代生物化学的发展和分子生物学的兴起","notes":"按“静态—动态—分子”三阶段讲，学生最容易记住。提醒：阶段不是截然断开，而是研究重点转移；1953年DNA双螺旋是标志性事件。","img":"assets/img/bc01deck/slide-10.jpg?v=20261108eg","points":["第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。","第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。","第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。","1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。"],"check":{"kind":"short","id":"bc01_s10_check","q":"本页「（一）现代生物化学的发展和分子生物学的兴起」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。；第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。；第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。；1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。","e":"解析：按“静态—动态—分子”三阶段讲，学生最容易记住。提醒：阶段不是截然断开，而是研究重点转移；1953年DNA双螺旋是标志性事件。 关键点：第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。；第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。；第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s10_exam","q":"关于本页「（一）现代生物化学的发展和分子生物学的兴起」，下列哪项表述正确？","o":["A. 分支距离表示序列差异程度，不表示“谁更高级”。","B. 第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。","C. 早期地球：还原性大气、强紫外线、雷电、火山活动。","D. APPENDIX · CALCULATION"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「图1-15 生物三域系统树」的内容，不是本页核心。","本页要点：第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。","属于「（一）最初的生物分子是通过化学进化产生的」的内容，不是本页核心。","属于「附录：计算题专项」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第10页","imageExplain":"这张图在讲：按“静态—动态—分子”三阶段讲，学生最容易记住。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。；第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。。","srcType":"原书","role":"查阅"},{"i":10,"sec":"第1章 原书版课件","title":"（二）现代生物化学发展中的一些重要学术中心和学者","notes":"人物不宜逐个背履历，抓住“贡献关键词”。Scheele—分离有机酸；Lavoisier—呼吸氧化；Liebig—代谢概念；Hoppe-Seyler—学科建立；Sumner—酶是蛋白质；Watson/Crick—双螺旋；Sanger—测序。","img":"assets/img/bc01deck/slide-11.jpg?v=20261108eg","points":["Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。","Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。","Hoppe-Seyler：建立生理化学学科，提出“biochemie”。","Pasteur、Fischer、Hopkins、Pavlov、Sumner 等推动微生物学、结构化学、维生素、消化生理与酶化学。"],"check":{"kind":"short","id":"bc01_s11_check","q":"本页「（二）现代生物化学发展中的一些重要学术中心和学者」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。；Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。；Hoppe-Seyler：建立生理化学学科，提出“biochemie”。；Pasteur、Fischer、Hopkins、Pavlov、Sumner 等推动微生物学、结构化学、维生素、消化生理与酶化学。","e":"解析：人物不宜逐个背履历，抓住“贡献关键词”。Scheele—分离有机酸；Lavoisier—呼吸氧化；Liebig—代谢概念；Hoppe-Seyler—学科建立；Sumner—酶是蛋白质；Watson/Crick—双螺旋；Sanger—测序。 关键点：Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。；Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。；Hoppe-Seyler：建立生理化学学科，提出“biochemie”。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s11_exam","q":"关于本页「（二）现代生物化学发展中的一些重要学术中心和学者」，下列哪项表述正确？","o":["A. 叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。","B. 图1-20是竖轴时间线，数值从下往上变小","C. Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。","D. 新陈代谢=合成代谢（同化）+分解代谢（异化）。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「图1-17 真核细胞结构模式图」的内容，不是本页核心。","属于「图1-20 地球上生命进化的里程碑」的内容，不是本页核心。","本页要点：Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。","属于「（二）利用环境的能量和物质进行自我更新」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第11页","imageExplain":"这张图在讲：人物不宜逐个背履历，抓住“贡献关键词”。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。；Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。。","srcType":"原书","role":"查阅"},{"i":11,"sec":"第1章 原书版课件","title":"（三）发展中的我国生物化学","notes":"这一页兼顾古代实践与现代成就。重点讲“曲”与酶的关系、牛胰岛素人工合成，既能体现学科历史，也能联系蛋白质结构与功能。","img":"assets/img/bc01deck/slide-12.jpg?v=20261108eg","points":["古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。","“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。","《黄帝内经》提出“五谷为养，五畜为益，五果为助，五菜为充”。","现代：吴宪等在蛋白质变性等方面奠基；1965年人工合成牛胰岛素。"],"check":{"kind":"short","id":"bc01_s12_check","q":"本页「（三）发展中的我国生物化学」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。；“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。；《黄帝内经》提出“五谷为养，五畜为益，五果为助，五菜为充”。；现代：吴宪等在蛋白质变性等方面奠基；1965年人工合成牛胰岛素。","e":"解析：这一页兼顾古代实践与现代成就。重点讲“曲”与酶的关系、牛胰岛素人工合成，既能体现学科历史，也能联系蛋白质结构与功能。 关键点：古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。；“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。；《黄帝内经》提出“五谷为养，五畜为益，五果为助，五菜为充”。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s12_exam","q":"关于本页「（三）发展中的我国生物化学」，下列哪项表述正确？","o":["A. “RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。","B. ① 0.4 mol/L NaOH 500 mL","C. 1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。","D. 古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（二）RNA或相关前体可能是最早的基因和催化剂」的内容，不是本页核心。","属于「例题：溶液配制、pH 与缓冲液」的内容，不是本页核心。","属于「（一）现代生物化学的发展和分子生物学的兴起」的内容，不是本页核心。","本页要点：古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。"],"src":"期末·选择题"},"source":"老师第1章PPT 第12页","imageExplain":"这张图在讲：这一页兼顾古代实践与现代成就。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。；“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。。","srcType":"原书","role":"查阅"},{"i":12,"sec":"第1章 原书版课件","title":"第2节 · 3句话 + 2题自测","notes":"第2节收束：按“静态—动态—分子”三阶段记忆，人物抓贡献关键词。","img":"","points":["现代生物化学大体经历静态、动态、分子三个阶段。","1953 年 DNA 双螺旋模型开启分子生物学；分子生物学研究 DNA、RNA、蛋白质及其关系。","中国学者在蛋白质变性、牛胰岛素与 tRNA 人工合成等方面作出重要贡献。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap2_1","kind":"mcq","q":"现代生物化学三个阶段的顺序是？","o":["A. 静态→动态→分子","B. 动态→静态→分子","C. 分子→动态→静态","D. 静态→分子→动态"],"a":"A","e":"三个阶段：静态/叙述（组成结构）→动态（代谢酶）→分子（大分子机制）。","oe":["顺序正确。","顺序错误。","顺序错误。","顺序错误。"],"src":"本节收束"},{"id":"bc01_wrap2_2","kind":"mcq","q":"1953年的标志性事件是？","o":["A. 第一个酶结晶","B. DNA双螺旋模型","C. PCR发明","D. 基因编辑"],"a":"B","e":"1953年Watson和Crick提出DNA双螺旋模型，开启分子生物学。","oe":["Sumner结晶脲酶更早。","正确。","PCR是1980年代。","基因编辑更晚。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":13,"sec":"第1章 原书版课件","title":"第2节难点：三阶段怎么记？","notes":"第2节难点：用研究重点和标志事件记三阶段，不要背年份流水账。","img":"","points":["静态：组成、分离、结构；动态：代谢、酶、能量；分子：大分子与机制。","1953 DNA双螺旋；重组DNA、测序、基因编辑。","吴宪、牛胰岛素、tRNA人工合成。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break14","kind":"short","q":"用“研究重点+标志事件”复述生物化学三阶段。","a":"得分点：静态（组成结构）→动态（代谢酶）→分子（大分子机制）；1953 DNA双螺旋。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":14,"sec":"第1章 原书版课件","title":"生命物质的化学组成","notes":"本节导览：生命元素如何分类？；为什么说生物分子是碳的化合物？；小分子、大分子与单体是什么关系？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-15.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第15页","imageExplain":"这张图在讲：本节导览：生命元素如何分类？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":15,"sec":"第1章 原书版课件","title":"（一）生命元素","notes":"区分“大量/微量”按含量，不按重要性；微量元素含量低但常不可替代。考试常考：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。","img":"assets/img/bc01deck/slide-16.jpg?v=20261108eg","points":["大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。","微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。","C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。","大量元素构成水和有机物；微量元素多作为酶、辅酶或激素的组成成分。"],"check":{"kind":"short","id":"bc01_s16_check","q":"本页「（一）生命元素」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。；微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。；C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。；大量元素构成水和有机物；微量元素多作为酶、辅酶或激素的组成成分。","e":"解析：区分“大量/微量”按含量，不按重要性；微量元素含量低但常不可替代。考试常考：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。 关键点：大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。；微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。；C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s16_exam","q":"关于本页「（一）生命元素」，下列哪项表述正确？","o":["A. 1953 年 DNA 双螺旋模型开启分子生物学；分子生物学研究 DNA、RNA、蛋白质及其关系。","B. R 是占位基团，不代表某一种固定原子。","C. L-氨基酸、D-单糖是生物体常用的构型。","D. 大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第2节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「图1-3 局部放大（上）：含氧官能团」的内容，不是本页核心。","属于「（三）构型的命名系统」的内容，不是本页核心。","本页要点：大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。"],"src":"期末·选择题"},"source":"老师第1章PPT 第16页","imageExplain":"这张图在讲：区分“大量/微量”按含量，不按重要性。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。；微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。。","srcType":"原书","role":"查阅"},{"i":16,"sec":"第1章 原书版课件","title":"（二）生物分子是碳的化合物","notes":"强调碳的“四价”和“成链/成环”能力。官能团决定化学性质，碳骨架决定分子形状；二者共同决定生物分子功能。","img":"assets/img/bc01deck/slide-17.jpg?v=20261108eg","points":["碳原子四价，可形成四个稳定共价键。","碳链可长可短、可分支、可成环，并可连接多种官能团。","常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。","碳骨架的多样性 → 生物分子种类繁多、功能多样。"],"check":{"kind":"short","id":"bc01_s17_check","q":"本页「（二）生物分子是碳的化合物」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：碳原子四价，可形成四个稳定共价键。；碳链可长可短、可分支、可成环，并可连接多种官能团。；常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。；碳骨架的多样性 → 生物分子种类繁多、功能多样。","e":"解析：强调碳的“四价”和“成链/成环”能力。官能团决定化学性质，碳骨架决定分子形状；二者共同决定生物分子功能。 关键点：碳原子四价，可形成四个稳定共价键。；碳链可长可短、可分支、可成环，并可连接多种官能团。；常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s17_exam","q":"关于本页「（二）生物分子是碳的化合物」，下列哪项表述正确？","o":["A. 碳原子四价，可形成四个稳定共价键。","B. A：4 个单键指向四面体四个顶点，键角约 109.5°。","C. 蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。","D. 球棍模型：球代表原子、棒代表键，突出键角和空间关系。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：碳原子四价，可形成四个稳定共价键。","属于「图1-2 碳成键的几何学」的内容，不是本页核心。","属于「（一）生物分子的大小」的内容，不是本页核心。","属于「图1-9 三维结构的分子模型（L-丝氨酸）」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第17页","imageExplain":"这张图在讲：强调碳的“四价”和“成链/成环”能力。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：碳原子四价，可形成四个稳定共价键。；碳链可长可短、可分支、可成环，并可连接多种官能团。。","srcType":"原书","role":"查阅"},{"i":17,"sec":"第1章 原书版课件","title":"图1-1 碳原子成键的多能性","notes":"图1-1展示碳的成键多能性。重点不是背反应式，而是理解碳能形成稳定单键、双键、三键，从而构建多样碳骨架。","img":"assets/img/bc01deck/slide-18.jpg?v=20261108eg","points":["碳原子四价：可形成 4 个共价键。","既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。","单键、双键、三键的成键数目不同，决定分子的几何与反应性。","生物分子以碳骨架为基础，但三键在生物分子中较少见。"],"imageExplain":"本页为原书配图：图1-1 碳原子成键的多能性。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s18_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：碳原子四价：可形成 4 个共价键。；既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。；单键、双键、三键的成键数目不同，决定分子的几何与反应性。；生物分子以碳骨架为基础，但三键在生物分子中较少见。","e":"解析：图1-1展示碳的成键多能性。重点不是背反应式，而是理解碳能形成稳定单键、双键、三键，从而构建多样碳骨架。 关键点：碳原子四价：可形成 4 个共价键。；既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。；单键、双键、三键的成键数目不同，决定分子的几何与反应性。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s18_exam","q":"关于本页「图1-1 碳原子成键的多能性」，下列哪项表述正确？","o":["A. 带电基团注意正负号：—COO⁻、—NH₃⁺。","B. 碳原子四价：可形成 4 个共价键。","C. Fischer 投影式：水平键朝向观察者，垂直键远离观察者。","D. 具有方向性和饱和性，强度介于共价键和范德华力之间。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「图1-3 局部放大（下）：含氮/含硫/含磷官能团」的内容，不是本页核心。","本页要点：碳原子四价：可形成 4 个共价键。","属于「图1-5 甘油醛的构型（D/L 命名系统）」的内容，不是本页核心。","属于「（二）氢键」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第18页","srcType":"原书","role":"查阅"},{"i":18,"sec":"第1章 原书版课件","title":"图1-2 碳成键的几何学","notes":"图1-2把碳的几何学讲清楚：四面体、单键旋转、双键平面。它是后面构型/构象和顺反异构的基础。","img":"assets/img/bc01deck/slide-19.jpg?v=20261108eg","points":["A：4 个单键指向四面体四个顶点，键角约 109.5°。","B：C—C 单键可绕键轴自由旋转，产生不同构象。","C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。","单键旋转 → 构象；双键限制旋转 → 顺反异构。"],"imageExplain":"本页为原书配图：图1-2 碳成键的几何学。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s19_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：A：4 个单键指向四面体四个顶点，键角约 109.5°。；B：C—C 单键可绕键轴自由旋转，产生不同构象。；C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。；单键旋转 → 构象；双键限制旋转 → 顺反异构。","e":"解析：图1-2把碳的几何学讲清楚：四面体、单键旋转、双键平面。它是后面构型/构象和顺反异构的基础。 关键点：A：4 个单键指向四面体四个顶点，键角约 109.5°。；B：C—C 单键可绕键轴自由旋转，产生不同构象。；C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s19_exam","q":"关于本页「图1-2 碳成键的几何学」，下列哪项表述正确？","o":["A. 构型包括对映体、非对映体和顺反异构。","B. 药物对映体可能一个有效、另一个无效甚至有害。","C. A：4 个单键指向四面体四个顶点，键角约 109.5°。","D. 疏水作用本质是水氢键网络的熵驱动，不是“油水相吸”。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（二）立体异构与构型」的内容，不是本页核心。","属于「（六）生物分子间的相互作用是立体专一的」的内容，不是本页核心。","本页要点：A：4 个单键指向四面体四个顶点，键角约 109.5°。","属于「第5节 · 3句话 + 2题自测」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第19页","srcType":"原书","role":"查阅"},{"i":19,"sec":"第1章 原书版课件","title":"（三）生物小分子与代谢物","notes":"把“构件”和“代谢物”两个身份讲清：同一个分子既可能是单体，也可能是代谢中间物。举例：乙酰CoA 是小分子，却是代谢枢纽。","img":"assets/img/bc01deck/slide-20.jpg?v=20261108eg","points":["生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。","代谢物是代谢途径中的中间产物和终产物。","小分子既是生物大分子的构件，也是能量代谢和信号分子。","单体通过共价聚合形成大分子；代谢物通过酶促反应相互转化。"],"check":{"kind":"short","id":"bc01_s20_check","q":"本页「（三）生物小分子与代谢物」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。；代谢物是代谢途径中的中间产物和终产物。；小分子既是生物大分子的构件，也是能量代谢和信号分子。；单体通过共价聚合形成大分子；代谢物通过酶促反应相互转化。","e":"解析：把“构件”和“代谢物”两个身份讲清：同一个分子既可能是单体，也可能是代谢中间物。举例：乙酰CoA 是小分子，却是代谢枢纽。 关键点：生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。；代谢物是代谢途径中的中间产物和终产物。；小分子既是生物大分子的构件，也是能量代谢和信号分子。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s20_exam","q":"关于本页「（三）生物小分子与代谢物」，下列哪项表述正确？","o":["A. 构象决定生物大分子的形状、活性和识别能力。","B. 作用距离很短，要求原子间紧密堆积。","C. 包括蒸汽压下降、沸点升高、凝固点降低、渗透压。","D. 生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）构象」的内容，不是本页核心。","属于「（三）范德华力」的内容，不是本页核心。","属于「（三）溶质影响水的依数性」的内容，不是本页核心。","本页要点：生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。"],"src":"期末·选择题"},"source":"老师第1章PPT 第20页","imageExplain":"这张图在讲：把“构件”和“代谢物”两个身份讲清：同一个分子既可能是单体，也可能是代谢中间物。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。；代谢物是代谢途径中的中间产物和终产物。。","srcType":"原书","role":"查阅"},{"i":20,"sec":"第1章 原书版课件","title":"图1-3 生物分子中常见官能团","notes":"图1-3是官能团总表。学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键。不要只背结构，要能判断性质。","img":"assets/img/bc01deck/slide-21.jpg?v=20261108eg","points":["图1-3是官能团总表","学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键","不要只背结构，要能判断性质"],"check":{"kind":"short","id":"bc01_s21_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-3是官能团总表；学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键；不要只背结构，要能判断性质","e":"解析：图1-3是官能团总表。学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键。不要只背结构，要能判断性质。 关键点：图1-3是官能团总表；学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键；不要只背结构，要能判断性质","src":"本页自测"},"imageExplain":"本页为原书配图：图1-3 生物分子中常见官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s21_exam","q":"关于本页「图1-3 生物分子中常见官能团」，下列哪项表述正确？","o":["A. 图1-3是官能团总表","B. 连四个不同基团的碳；对映体互为镜像、不能重合。","C. 每个水分子最多形成4个氢键，形成动态网络。","D. 系统树基于 rRNA 序列相似性：序列越相似，分支越接近。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：图1-3是官能团总表","属于「第4节难点：构型、构象与D/L」的内容，不是本页核心。","属于「（一）水的结构和性质」的内容，不是本页核心。","属于「图1-15 生物三域系统树」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第21页","srcType":"原书","role":"查阅"},{"i":21,"sec":"第1章 原书版课件","title":"图1-3 局部放大（上）：含氧官能团","notes":"图1-3上半局部：含氧官能团。放大后逐个核对名称和结构式，不要只看灰底方块。","img":"assets/img/bc01deck/slide-22.jpg?v=20261108eg","points":["先看“名称—结构式”一一对应。","重点认羟基、羰基、羧基、酯基、磷酸基。","R 是占位基团，不代表某一种固定原子。","含氧基团决定极性和氢键能力。"],"imageExplain":"本页为原书配图：图1-3 局部放大（上）：含氧官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s22_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：先看“名称—结构式”一一对应。；重点认羟基、羰基、羧基、酯基、磷酸基。；R 是占位基团，不代表某一种固定原子。；含氧基团决定极性和氢键能力。","e":"解析：图1-3上半局部：含氧官能团。放大后逐个核对名称和结构式，不要只看灰底方块。 关键点：先看“名称—结构式”一一对应。；重点认羟基、羰基、羧基、酯基、磷酸基。；R 是占位基团，不代表某一种固定原子。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s22_exam","q":"关于本页「图1-3 局部放大（上）：含氧官能团」，下列哪项表述正确？","o":["A. 疏水作用是膜脂双层形成、蛋白质折叠的重要驱动力。","B. 先看“名称—结构式”一一对应。","C. Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。","D. 高尔基体：加工、分选和运输；溶酶体：降解。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）疏水相互作用」的内容，不是本页核心。","本页要点：先看“名称—结构式”一一对应。","属于「（四）水、弱酸和弱碱的电离」的内容，不是本页核心。","属于「（四）真核细胞含有多种膜性细胞器」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第22页","srcType":"原书","role":"查阅"},{"i":22,"sec":"第1章 原书版课件","title":"图1-3 局部放大（下）：含氮/含硫/含磷官能团","notes":"图1-3下半局部：含氮、含硫、含磷官能团。重点区分氨基/酰胺/亚氨基，以及磷酸酐/混合酐。","img":"assets/img/bc01deck/slide-23.jpg?v=20261108eg","points":["氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。","巯基（—SH）可形成二硫键；硫酯基参与酰基转移。","磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。","带电基团注意正负号：—COO⁻、—NH₃⁺。"],"imageExplain":"本页为原书配图：图1-3 局部放大（下）：含氮/含硫/含磷官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s23_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。；巯基（—SH）可形成二硫键；硫酯基参与酰基转移。；磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。；带电基团注意正负号：—COO⁻、—NH₃⁺。","e":"解析：图1-3下半局部：含氮、含硫、含磷官能团。重点区分氨基/酰胺/亚氨基，以及磷酸酐/混合酐。 关键点：氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。；巯基（—SH）可形成二硫键；硫酯基参与酰基转移。；磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s23_exam","q":"关于本页「图1-3 局部放大（下）：含氮/含硫/含磷官能团」，下列哪项表述正确？","o":["A. C：水分子通过氢键连成三维网络，可看出六元环排列。","B. 单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。","C. 氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。","D. 米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「图1-12 水分子结构与冰中氢键」的内容，不是本页核心。","属于「（二）细胞是所有生物的结构和功能单位」的内容，不是本页核心。","本页要点：氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。","属于「（一）最初的生物分子是通过化学进化产生的」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第23页","srcType":"原书","role":"查阅"},{"i":23,"sec":"第1章 原书版课件","title":"（四）生物大分子及其单体亚基","notes":"这一页是全章高频考点：三大类生物大分子与单体对应关系、5000这个界限、脂质的特殊地位。强调“序列决定结构，结构决定功能”。","img":"assets/img/bc01deck/slide-24.jpg?v=20261108eg","points":["蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。","生物大分子通常指相对分子质量大于5000的多聚体。","单体排列顺序决定大分子的一级结构，进而决定高级结构和功能。","脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。"],"check":{"kind":"short","id":"bc01_s24_check","q":"本页「（四）生物大分子及其单体亚基」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。；生物大分子通常指相对分子质量大于5000的多聚体。；单体排列顺序决定大分子的一级结构，进而决定高级结构和功能。；脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。","e":"解析：这一页是全章高频考点：三大类生物大分子与单体对应关系、5000这个界限、脂质的特殊地位。强调“序列决定结构，结构决定功能”。 关键点：蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。；生物大分子通常指相对分子质量大于5000的多聚体。；单体排列顺序决定大分子的一级结构，进而决定高级结构和功能。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s24_exam","q":"关于本页「（四）生物大分子及其单体亚基」，下列哪项表述正确？","o":["A. pH = pKa + lg([A⁻]/[HA])；[A⁻]=盐，[HA]=酸。","B. 三域：细菌、古菌、真核；前两者为原核，无核膜。","C. 化学进化：无机小分子→有机小分子→生物大分子。","D. 蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第6节难点：缓冲液计算三步走」的内容，不是本页核心。","属于「第7节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「第8节 · 3句话 + 2题自测」的内容，不是本页核心。","本页要点：蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。"],"src":"期末·选择题"},"source":"老师第1章PPT 第24页","imageExplain":"这张图在讲：这一页是全章高频考点：三大类生物大分子与单体对应关系、5000这个界限、脂质的特殊地位。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。；生物大分子通常指相对分子质量大于5000的多聚体。。","srcType":"原书","role":"查阅"},{"i":24,"sec":"第1章 原书版课件","title":"第3节 · 3句话 + 2题自测","notes":"第3节收束：元素→碳骨架→小分子→大分子，层层递进。","img":"","points":["生命元素分大量元素与微量元素；C、H、O、N 占主要质量。","碳四价、可成链/成环，官能团决定极性与化学反应性。","蛋白质—氨基酸、核酸—核苷酸、多糖—单糖；生物大分子通常 M>5000。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap3_1","kind":"mcq","q":"下列属于微量元素的是？","o":["A. 碳","B. 铁","C. 氧","D. 氮"],"a":"B","e":"Fe属于微量元素；C、O、N是大量元素。","oe":["碳是大量元素。","铁是微量元素。","氧是大量元素。","氮是大量元素。"],"src":"本节收束"},{"id":"bc01_wrap3_2","kind":"mcq","q":"蛋白质、核酸、多糖的单体依次是？","o":["A. 氨基酸、核苷酸、单糖","B. 单糖、氨基酸、核苷酸","C. 核苷酸、单糖、氨基酸","D. 脂肪酸、氨基酸、核苷酸"],"a":"A","e":"蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。","oe":["正确。","顺序错误。","顺序错误。","脂肪酸不是蛋白质单体。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":25,"sec":"第1章 原书版课件","title":"第3节难点：从小分子到大分子","notes":"第3节难点：用“元素→单体→大分子→超分子”四级层次组织知识。","img":"","points":["大量元素+微量元素；C、H、O、N为主。","氨基酸→蛋白质；核苷酸→核酸；单糖→多糖；共价连接。","超分子复合体→细胞器→细胞；主要靠非共价作用。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break26","kind":"short","q":"用“元素→单体→大分子→超分子”四级层次复述本节。","a":"得分点：生命元素→氨基酸/核苷酸/单糖→蛋白质/核酸/多糖→超分子复合体→细胞器/细胞；脂质是准大分子。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":26,"sec":"第1章 原书版课件","title":"生物分子的三维结构：构型与构象","notes":"本节导览：构型与构象的本质区别是什么？；手性碳和对映体如何判断？；生物分子间的识别为什么是立体专一的？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-27.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第27页","imageExplain":"这张图在讲：本节导览：构型与构象的本质区别是什么？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":27,"sec":"第1章 原书版课件","title":"（一）生物分子的大小","notes":"用数量级建立尺度感：小分子Å—nm，蛋白质nm，细胞µm。提醒学生：生物大分子不是“越大越好”，功能取决于结构和相互作用。","img":"assets/img/bc01deck/slide-28.jpg?v=20261108eg","points":["小分子：相对分子质量几十到几百；生物大分子：通常 >5000。","蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。","核糖体、病毒、细胞器属于更大的超分子复合体。","生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。"],"check":{"kind":"short","id":"bc01_s28_check","q":"本页「（一）生物分子的大小」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：小分子：相对分子质量几十到几百；生物大分子：通常 >5000。；蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。；核糖体、病毒、细胞器属于更大的超分子复合体。；生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。","e":"解析：用数量级建立尺度感：小分子Å—nm，蛋白质nm，细胞µm。提醒学生：生物大分子不是“越大越好”，功能取决于结构和相互作用。 关键点：小分子：相对分子质量几十到几百；生物大分子：通常 >5000。；蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。；核糖体、病毒、细胞器属于更大的超分子复合体。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s28_exam","q":"关于本页「（一）生物分子的大小」，下列哪项表述正确？","o":["A. APPENDIX · CALCULATION","B. 生命是开放系统，靠能量流维持低熵有序。","C. 既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。","D. 小分子：相对分子质量几十到几百；生物大分子：通常 >5000。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「附录：计算题专项」的内容，不是本页核心。","属于「第1节难点：生命属性怎么答？」的内容，不是本页核心。","属于「图1-1 碳原子成键的多能性」的内容，不是本页核心。","本页要点：小分子：相对分子质量几十到几百；生物大分子：通常 >5000。"],"src":"期末·选择题"},"source":"老师第1章PPT 第28页","imageExplain":"这张图在讲：用数量级建立尺度感：小分子Å—nm，蛋白质nm，细胞µm。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：小分子：相对分子质量几十到几百；生物大分子：通常 >5000。；蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。。","srcType":"原书","role":"查阅"},{"i":28,"sec":"第1章 原书版课件","title":"（二）立体异构与构型","notes":"先区分“连接次序”与“空间排列”，再讲构型。判断手性碳只看四个基团是否不同，不看碳上连了几根键。构型是“换了就回不去”的稳定空间排列。","img":"assets/img/bc01deck/slide-29.jpg?v=20261108eg","points":["结构异构：原子连接次序不同。","立体异构：连接次序相同，空间排列不同。","构型包括对映体、非对映体和顺反异构。","构型改变必须断裂共价键，不能靠单键旋转互变。"],"check":{"kind":"short","id":"bc01_s29_check","q":"本页「（二）立体异构与构型」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：结构异构：原子连接次序不同。；立体异构：连接次序相同，空间排列不同。；构型包括对映体、非对映体和顺反异构。；构型改变必须断裂共价键，不能靠单键旋转互变。","e":"解析：先区分“连接次序”与“空间排列”，再讲构型。判断手性碳只看四个基团是否不同，不看碳上连了几根键。构型是“换了就回不去”的稳定空间排列。 关键点：结构异构：原子连接次序不同。；立体异构：连接次序相同，空间排列不同。；构型包括对映体、非对映体和顺反异构。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s29_exam","q":"关于本页「（二）立体异构与构型」，下列哪项表述正确？","o":["A. 结构异构：原子连接次序不同。","B. 新陈代谢=合成代谢（同化）+分解代谢（异化）。","C. 静态：组成、分离、结构；动态：代谢、酶、能量；分子：大分子与机制。","D. 氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：结构异构：原子连接次序不同。","属于「（二）利用环境的能量和物质进行自我更新」的内容，不是本页核心。","属于「第2节难点：三阶段怎么记？」的内容，不是本页核心。","属于「图1-3 局部放大（下）：含氮/含硫/含磷官能团」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第29页","imageExplain":"这张图在讲：先区分“连接次序”与“空间排列”，再讲构型。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：结构异构：原子连接次序不同。；立体异构：连接次序相同，空间排列不同。。","srcType":"原书","role":"查阅"},{"i":29,"sec":"第1章 原书版课件","title":"图1-4 立体异构体的构型","notes":"图1-4是“构型”最重要的原图：上半部分讲顺反异构，下半部分讲对映体。要能指出哪些基团在同侧/异侧，以及D/L互为镜像。","img":"assets/img/bc01deck/slide-30.jpg?v=20261108eg","points":["A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。","A 下：顺-1,4-环己二醇与反-1,4-环己二醇，环限制旋转造成顺反差异。","B：L(−)-甘油醛与 D(+)-甘油醛，互为镜像、不能重合，是一对对映体。","构型改变需要断裂共价键；顺反异构和对映异构都属于构型异构。"],"imageExplain":"本页为原书配图：图1-4 立体异构体的构型。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s30_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。；A 下：顺-1,4-环己二醇与反-1,4-环己二醇，环限制旋转造成顺反差异。；B：L(−)-甘油醛与 D(+)-甘油醛，互为镜像、不能重合，是一对对映体。；构型改变需要断裂共价键；顺反异构和对映异构都属于构型异构。","e":"解析：图1-4是“构型”最重要的原图：上半部分讲顺反异构，下半部分讲对映体。要能指出哪些基团在同侧/异侧，以及D/L互为镜像。 关键点：A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。；A 下：顺-1,4-环己二醇与反-1,4-环己二醇，环限制旋转造成顺反差异。；B：L(−)-甘油醛与 D(+)-甘油醛，互为镜像、不能重合，是一对对映体。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s30_exam","q":"关于本页「图1-4 立体异构体的构型」，下列哪项表述正确？","o":["A. 1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。","B. A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。","C. C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。","D. 生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）现代生物化学的发展和分子生物学的兴起」的内容，不是本页核心。","本页要点：A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。","属于「图1-2 碳成键的几何学」的内容，不是本页核心。","属于「（一）生物分子的大小」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第30页","srcType":"原书","role":"查阅"},{"i":30,"sec":"第1章 原书版课件","title":"（三）构型的命名系统","notes":"易错点：D/L 不是“左/右旋”，而是相对甘油醛的构型；R/S 按原子序数排优先级。L-氨基酸与D-单糖是常见记忆点。","img":"assets/img/bc01deck/slide-31.jpg?v=20261108eg","points":["D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。","L-氨基酸、D-单糖是生物体常用的构型。","R/S 命名：按 CIP 规则给四个基团排优先级，再看空间方向。","D/L 与 R/S 是两套独立系统，不能简单等同。"],"check":{"kind":"short","id":"bc01_s31_check","q":"本页「（三）构型的命名系统」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。；L-氨基酸、D-单糖是生物体常用的构型。；R/S 命名：按 CIP 规则给四个基团排优先级，再看空间方向。；D/L 与 R/S 是两套独立系统，不能简单等同。","e":"解析：易错点：D/L 不是“左/右旋”，而是相对甘油醛的构型；R/S 按原子序数排优先级。L-氨基酸与D-单糖是常见记忆点。 关键点：D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。；L-氨基酸、D-单糖是生物体常用的构型。；R/S 命名：按 CIP 规则给四个基团排优先级，再看空间方向。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s31_exam","q":"关于本页「（三）构型的命名系统」，下列哪项表述正确？","o":["A. C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。","B. 生物大分子通常指相对分子质量大于5000的多聚体。","C. D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。","D. 构象：同一构型下，通过单键旋转产生的不同空间形态。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）生命元素」的内容，不是本页核心。","属于「（四）生物大分子及其单体亚基」的内容，不是本页核心。","本页要点：D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。","属于「（四）构象」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第31页","imageExplain":"这张图在讲：易错点：D/L 不是“左/右旋”，而是相对甘油醛的构型。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。；L-氨基酸、D-单糖是生物体常用的构型。。","srcType":"原书","role":"查阅"},{"i":31,"sec":"第1章 原书版课件","title":"图1-5 甘油醛的构型（D/L 命名系统）","notes":"图1-5把Fischer式、透视式、立体模型放在同一镜面两侧，说明它们表示的是同一个构型问题。重点是会看Fischer式并判断D/L。","img":"assets/img/bc01deck/slide-32.jpg?v=20261108eg","points":["同一构型可用 Fischer 投影式、透视式、立体模型表示。","中央竖线为镜面，左右两组互为镜像，不能重合。","Fischer 投影式：水平键朝向观察者，垂直键远离观察者。","D/L 以甘油醛为参照；L-氨基酸、D-单糖是生物体常用构型。"],"imageExplain":"本页为原书配图：图1-5 甘油醛的构型（D/L 命名系统）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s32_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：同一构型可用 Fischer 投影式、透视式、立体模型表示。；中央竖线为镜面，左右两组互为镜像，不能重合。；Fischer 投影式：水平键朝向观察者，垂直键远离观察者。；D/L 以甘油醛为参照；L-氨基酸、D-单糖是生物体常用构型。","e":"解析：图1-5把Fischer式、透视式、立体模型放在同一镜面两侧，说明它们表示的是同一个构型问题。重点是会看Fischer式并判断D/L。 关键点：同一构型可用 Fischer 投影式、透视式、立体模型表示。；中央竖线为镜面，左右两组互为镜像，不能重合。；Fischer 投影式：水平键朝向观察者，垂直键远离观察者。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s32_exam","q":"关于本页「图1-5 甘油醛的构型（D/L 命名系统）」，下列哪项表述正确？","o":["A. 单体通过共价聚合形成大分子；代谢物通过酶促反应相互转化。","B. A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。","C. 手性碳连四个不同基团；对映体互为镜像、不能重合。","D. 同一构型可用 Fischer 投影式、透视式、立体模型表示。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（三）生物小分子与代谢物」的内容，不是本页核心。","属于「图1-4 立体异构体的构型」的内容，不是本页核心。","属于「第4节 · 3句话 + 2题自测」的内容，不是本页核心。","本页要点：同一构型可用 Fischer 投影式、透视式、立体模型表示。"],"src":"期末·选择题"},"source":"老师第1章PPT 第32页","srcType":"原书","role":"查阅"},{"i":32,"sec":"第1章 原书版课件","title":"（四）构象","notes":"用“构型换了回不去，构象转一下还能回来”帮助记忆。蛋白质的α螺旋、β折叠都是构象/二级结构，不是构型。这个区分是考试高频易错点。","img":"assets/img/bc01deck/slide-33.jpg?v=20261108eg","points":["构象：同一构型下，通过单键旋转产生的不同空间形态。","构象改变不需要断裂共价键，通常可快速互变。","例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。","构象决定生物大分子的形状、活性和识别能力。"],"check":{"kind":"short","id":"bc01_s33_check","q":"本页「（四）构象」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：构象：同一构型下，通过单键旋转产生的不同空间形态。；构象改变不需要断裂共价键，通常可快速互变。；例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。；构象决定生物大分子的形状、活性和识别能力。","e":"解析：用“构型换了回不去，构象转一下还能回来”帮助记忆。蛋白质的α螺旋、β折叠都是构象/二级结构，不是构型。这个区分是考试高频易错点。 关键点：构象：同一构型下，通过单键旋转产生的不同空间形态。；构象改变不需要断裂共价键，通常可快速互变。；例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s33_exam","q":"关于本页「（四）构象」，下列哪项表述正确？","o":["A. 构象：同一构型下，通过单键旋转产生的不同空间形态。","B. 蛋白质—氨基酸、核酸—核苷酸、多糖—单糖；生物大分子通常 M>5000。","C. 空间填充模型：显示原子实际占据空间，适合看分子外形。","D. 非极性基团在水中有避水聚集的倾向。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：构象：同一构型下，通过单键旋转产生的不同空间形态。","属于「第3节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「（五）三维结构的分子模型」的内容，不是本页核心。","属于「（四）疏水相互作用」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第33页","imageExplain":"这张图在讲：用“构型换了回不去，构象转一下还能回来”帮助记忆。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：构象：同一构型下，通过单键旋转产生的不同空间形态。；构象改变不需要断裂共价键，通常可快速互变。。","srcType":"原书","role":"查阅"},{"i":33,"sec":"第1章 原书版课件","title":"（五）三维结构的分子模型","notes":"让学生建立“模型目的不同”的意识：球棍看键，空间填充看体积，飘带看折叠。结构测定方法只需知道X射线、NMR、冷冻电镜三者的基本特点。","img":"assets/img/bc01deck/slide-34.jpg?v=20261108eg","points":["球棍模型：显示原子位置和化学键，适合看连接关系。","空间填充模型：显示原子实际占据空间，适合看分子外形。","飘带/卡通模型：显示蛋白质二级结构和折叠，适合看整体构象。","X射线晶体学、NMR、冷冻电镜是主要结构测定方法。"],"check":{"kind":"short","id":"bc01_s34_check","q":"本页「（五）三维结构的分子模型」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：球棍模型：显示原子位置和化学键，适合看连接关系。；空间填充模型：显示原子实际占据空间，适合看分子外形。；飘带/卡通模型：显示蛋白质二级结构和折叠，适合看整体构象。；X射线晶体学、NMR、冷冻电镜是主要结构测定方法。","e":"解析：让学生建立“模型目的不同”的意识：球棍看键，空间填充看体积，飘带看折叠。结构测定方法只需知道X射线、NMR、冷冻电镜三者的基本特点。 关键点：球棍模型：显示原子位置和化学键，适合看连接关系。；空间填充模型：显示原子实际占据空间，适合看分子外形。；飘带/卡通模型：显示蛋白质二级结构和折叠，适合看整体构象。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s34_exam","q":"关于本页「（五）三维结构的分子模型」，下列哪项表述正确？","o":["A. L-氨基酸、D-单糖是生物体常用的构型。","B. 球棍模型：显示原子位置和化学键，适合看连接关系。","C. 带电基团之间的静电吸引或排斥。","D. 水的高介电常数使离子化合物易溶解。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（三）构型的命名系统」的内容，不是本页核心。","本页要点：球棍模型：显示原子位置和化学键，适合看连接关系。","属于「（一）离子相互作用」的内容，不是本页核心。","属于「（一）水的结构和性质」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第34页","imageExplain":"这张图在讲：让学生建立“模型目的不同”的意识：球棍看键，空间填充看体积，飘带看折叠。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：球棍模型：显示原子位置和化学键，适合看连接关系。；空间填充模型：显示原子实际占据空间，适合看分子外形。。","srcType":"原书","role":"查阅"},{"i":34,"sec":"第1章 原书版课件","title":"图1-9 三维结构的分子模型（L-丝氨酸）","notes":"图1-9用L-丝氨酸展示四种表示方法。模型没有“谁更高级”，只是强调的信息不同：连接、键角、体积。","img":"assets/img/bc01deck/slide-35.jpg?v=20261108eg","points":["透视式：用实线、楔形线、虚线表示三维朝向。","骨架模型：只显示键线骨架，突出连接次序。","球棍模型：球代表原子、棒代表键，突出键角和空间关系。","空间填充模型：按范德华半径显示真实占位，突出分子外形。"],"imageExplain":"本页为原书配图：图1-9 三维结构的分子模型（L-丝氨酸）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s35_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：透视式：用实线、楔形线、虚线表示三维朝向。；骨架模型：只显示键线骨架，突出连接次序。；球棍模型：球代表原子、棒代表键，突出键角和空间关系。；空间填充模型：按范德华半径显示真实占位，突出分子外形。","e":"解析：图1-9用L-丝氨酸展示四种表示方法。模型没有“谁更高级”，只是强调的信息不同：连接、键角、体积。 关键点：透视式：用实线、楔形线、虚线表示三维朝向。；骨架模型：只显示键线骨架，突出连接次序。；球棍模型：球代表原子、棒代表键，突出键角和空间关系。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s35_exam","q":"关于本页「图1-9 三维结构的分子模型（L-丝氨酸）」，下列哪项表述正确？","o":["A. 它们允许生物大分子在温和条件下组装和解离。","B. 水是极性分子，氢键网络带来高热容、高沸点、高表面张力。","C. 透视式：用实线、楔形线、虚线表示三维朝向。","D. 右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（五）非共价相互作用对大分子的结构和功能是关键的」的内容，不是本页核心。","属于「第6节 · 3句话 + 2题自测」的内容，不是本页核心。","本页要点：透视式：用实线、楔形线、虚线表示三维朝向。","属于「图1-17 真核细胞结构模式图」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第35页","srcType":"原书","role":"查阅"},{"i":35,"sec":"第1章 原书版课件","title":"（六）生物分子间的相互作用是立体专一的","notes":"从“锁钥/诱导契合”过渡到立体专一性。强调不是“形状像”就行，还要求电荷、氢键和手性匹配。药物手性例子能说明其现实意义。","img":"assets/img/bc01deck/slide-36.jpg?v=20261108eg","points":["酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。","结合位点的形状、电荷和氢键供受体必须互补。","手性识别是生物专一性的基础：对映体生物活性常不同。","药物对映体可能一个有效、另一个无效甚至有害。"],"check":{"kind":"short","id":"bc01_s36_check","q":"本页「（六）生物分子间的相互作用是立体专一的」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。；结合位点的形状、电荷和氢键供受体必须互补。；手性识别是生物专一性的基础：对映体生物活性常不同。；药物对映体可能一个有效、另一个无效甚至有害。","e":"解析：从“锁钥/诱导契合”过渡到立体专一性。强调不是“形状像”就行，还要求电荷、氢键和手性匹配。药物手性例子能说明其现实意义。 关键点：酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。；结合位点的形状、电荷和氢键供受体必须互补。；手性识别是生物专一性的基础：对映体生物活性常不同。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s36_exam","q":"关于本页「（六）生物分子间的相互作用是立体专一的」，下列哪项表述正确？","o":["A. 具有方向性和饱和性，强度介于共价键和范德华力之间。","B. 水占细胞质量的大部分，是物质运输和反应的介质。","C. 细胞体积小，有利于物质交换；表面积/体积比是关键。","D. 酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（二）氢键」的内容，不是本页核心。","属于「（二）水是生命的介质」的内容，不是本页核心。","属于「（二）细胞是所有生物的结构和功能单位」的内容，不是本页核心。","本页要点：酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。"],"src":"期末·选择题"},"source":"老师第1章PPT 第36页","imageExplain":"这张图在讲：从“锁钥/诱导契合”过渡到立体专一性。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。；结合位点的形状、电荷和氢键供受体必须互补。。","srcType":"原书","role":"查阅"},{"i":36,"sec":"第1章 原书版课件","title":"第4节 · 3句话 + 2题自测","notes":"第4节收束：先分构型/构象，再判断手性与D/L。","img":"","points":["构型改变需断共价键；构象改变只需单键旋转。","手性碳连四个不同基团；对映体互为镜像、不能重合。","D/L 以甘油醛为参照；生物体常用 L-氨基酸、D-单糖。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap4_1","kind":"mcq","q":"α螺旋变为β折叠属于？","o":["A. 结构异构","B. 构型改变","C. 构象改变","D. 共价键断裂"],"a":"C","e":"α螺旋和β折叠都是二级结构，通过单键旋转互变，属于构象改变。","oe":["结构异构是连接次序不同。","构型改变需断共价键。","正确。","没有共价键断裂。"],"src":"本节收束"},{"id":"bc01_wrap4_2","kind":"mcq","q":"D/L命名以什么为参照？","o":["A. 葡萄糖","B. 甘油醛","C. 丙氨酸","D. 乳酸"],"a":"B","e":"D/L命名以甘油醛为参照，常用于糖和氨基酸。","oe":["葡萄糖用D/L但参照甘油醛。","正确。","丙氨酸是D/L应用对象。","乳酸不是参照。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":37,"sec":"第1章 原书版课件","title":"第4节难点：构型、构象与D/L","notes":"第4节难点：先判断断不断键，再判断手性，最后用Fischer式定D/L。","img":"","points":["要断共价键→构型；只绕单键转→构象。","连四个不同基团的碳；对映体互为镜像、不能重合。","水平键朝前、垂直键朝后；与甘油醛比较定D/L。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break38","kind":"short","q":"如何判断构型与构象？D/L看什么？","a":"得分点：断共价键→构型；单键旋转→构象；手性碳连四个不同基团；Fischer式与甘油醛比较定D/L。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":38,"sec":"第1章 原书版课件","title":"生物系统中的非共价相互作用","notes":"本节导览：生物系统中主要有哪四类非共价作用？；它们为什么能稳定生物大分子？；疏水作用为什么常是折叠的主要驱动力？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-39.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第39页","imageExplain":"这张图在讲：本节导览：生物系统中主要有哪四类非共价作用？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":39,"sec":"第1章 原书版课件","title":"（一）离子相互作用","notes":"离子键本质是静电作用。注意环境：水的高介电常数会削弱静电吸引；高盐会屏蔽电荷。蛋白质盐析、离子交换层析都与离子作用有关。","img":"assets/img/bc01deck/slide-40.jpg?v=20261108eg","points":["带电基团之间的静电吸引或排斥。","蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。","DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。","强度受介电常数、离子强度和环境 pH 影响。"],"check":{"kind":"short","id":"bc01_s40_check","q":"本页「（一）离子相互作用」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：带电基团之间的静电吸引或排斥。；蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。；DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。；强度受介电常数、离子强度和环境 pH 影响。","e":"解析：离子键本质是静电作用。注意环境：水的高介电常数会削弱静电吸引；高盐会屏蔽电荷。蛋白质盐析、离子交换层析都与离子作用有关。 关键点：带电基团之间的静电吸引或排斥。；蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。；DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s40_exam","q":"关于本页「（一）离子相互作用」，下列哪项表述正确？","o":["A. 高尔基体：加工、分选和运输；溶酶体：降解。","B. 叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。","C. 蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。","D. 带电基团之间的静电吸引或排斥。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）真核细胞含有多种膜性细胞器」的内容，不是本页核心。","属于「（四）真核细胞是从原核细胞进化而来的」的内容，不是本页核心。","属于「（一）化学成分复杂而同一、结构错综而有序」的内容，不是本页核心。","本页要点：带电基团之间的静电吸引或排斥。"],"src":"期末·选择题"},"source":"老师第1章PPT 第40页","imageExplain":"这张图在讲：离子键本质是静电作用。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：带电基团之间的静电吸引或排斥。；蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。。","srcType":"原书","role":"查阅"},{"i":40,"sec":"第1章 原书版课件","title":"（二）氢键","notes":"氢键不是“氢原子之间的键”，而是H与孤对电子之间的作用。方向性使氢键具有立体专一性；G≡C三个氢键解释DNA稳定性差异。","img":"assets/img/bc01deck/slide-41.jpg?v=20261108eg","points":["氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。","具有方向性和饱和性，强度介于共价键和范德华力之间。","DNA碱基配对：A=T 两个氢键，G≡C 三个氢键。","蛋白质二级结构：α螺旋、β折叠靠主链氢键稳定。"],"check":{"kind":"short","id":"bc01_s41_check","q":"本页「（二）氢键」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。；具有方向性和饱和性，强度介于共价键和范德华力之间。；DNA碱基配对：A=T 两个氢键，G≡C 三个氢键。；蛋白质二级结构：α螺旋、β折叠靠主链氢键稳定。","e":"解析：氢键不是“氢原子之间的键”，而是H与孤对电子之间的作用。方向性使氢键具有立体专一性；G≡C三个氢键解释DNA稳定性差异。 关键点：氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。；具有方向性和饱和性，强度介于共价键和范德华力之间。；DNA碱基配对：A=T 两个氢键，G≡C 三个氢键。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s41_exam","q":"关于本页「（二）氢键」，下列哪项表述正确？","o":["A. 氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。","B. 米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。","C. NaOH: i=2；葡萄糖: i=1","D. 第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。","属于「（一）最初的生物分子是通过化学进化产生的」的内容，不是本页核心。","属于「计算工具箱：四个公式解决本章计算」的内容，不是本页核心。","属于「（一）现代生物化学的发展和分子生物学的兴起」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第41页","imageExplain":"这张图在讲：氢键不是“氢原子之间的键”，而是H与孤对电子之间的作用。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。；具有方向性和饱和性，强度介于共价键和范德华力之间。。","srcType":"原书","role":"查阅"},{"i":41,"sec":"第1章 原书版课件","title":"（三）范德华力","notes":"范德华力常被忽略，但大量紧密堆积的原子间作用对结构稳定很重要。强调“距离短、数量多”的特点。","img":"assets/img/bc01deck/slide-42.jpg?v=20261108eg","points":["瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。","包括取向力、诱导力、色散力；色散力最普遍。","作用距离很短，要求原子间紧密堆积。","在疏水核心、分子内部堆积中贡献显著。"],"check":{"kind":"short","id":"bc01_s42_check","q":"本页「（三）范德华力」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。；包括取向力、诱导力、色散力；色散力最普遍。；作用距离很短，要求原子间紧密堆积。；在疏水核心、分子内部堆积中贡献显著。","e":"解析：范德华力常被忽略，但大量紧密堆积的原子间作用对结构稳定很重要。强调“距离短、数量多”的特点。 关键点：瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。；包括取向力、诱导力、色散力；色散力最普遍。；作用距离很短，要求原子间紧密堆积。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s42_exam","q":"关于本页「（三）范德华力」，下列哪项表述正确？","o":["A. 化学进化：无机小分子→有机小分子→生物大分子。","B. 瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。","C. 分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。","D. 吴宪、牛胰岛素、tRNA人工合成。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第8节 · 3句话 + 2题自测」的内容，不是本页核心。","本页要点：瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。","属于「（二）利用环境的能量和物质进行自我更新」的内容，不是本页核心。","属于「第2节难点：三阶段怎么记？」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第42页","imageExplain":"这张图在讲：范德华力常被忽略，但大量紧密堆积的原子间作用对结构稳定很重要。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。；包括取向力、诱导力、色散力；色散力最普遍。。","srcType":"原书","role":"查阅"},{"i":42,"sec":"第1章 原书版课件","title":"（四）疏水相互作用","notes":"这是最容易被误解的一条：疏水作用不是“油水相斥”的简单吸引，而是水分子为了维持氢键网络产生的熵驱动。用“熵驱动”四个字点明本质。","img":"assets/img/bc01deck/slide-43.jpg?v=20261108eg","points":["非极性基团在水中有避水聚集的倾向。","本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。","蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。","疏水作用是膜脂双层形成、蛋白质折叠的重要驱动力。"],"check":{"kind":"short","id":"bc01_s43_check","q":"本页「（四）疏水相互作用」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：非极性基团在水中有避水聚集的倾向。；本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。；蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。；疏水作用是膜脂双层形成、蛋白质折叠的重要驱动力。","e":"解析：这是最容易被误解的一条：疏水作用不是“油水相斥”的简单吸引，而是水分子为了维持氢键网络产生的熵驱动。用“熵驱动”四个字点明本质。 关键点：非极性基团在水中有避水聚集的倾向。；本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。；蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s43_exam","q":"关于本页「（四）疏水相互作用」，下列哪项表述正确？","o":["A. m=0.20×40=8.0 g","B. Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。","C. 非极性基团在水中有避水聚集的倾向。","D. 生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「例题：溶液配制、pH 与缓冲液」的内容，不是本页核心。","属于「（二）现代生物化学发展中的一些重要学术中心和学者」的内容，不是本页核心。","本页要点：非极性基团在水中有避水聚集的倾向。","属于「（三）生物小分子与代谢物」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第43页","imageExplain":"这张图在讲：这是最容易被误解的一条：疏水作用不是“油水相斥”的简单吸引，而是水分子为了维持氢键网络产生的熵驱动。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：非极性基团在水中有避水聚集的倾向。；本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。。","srcType":"原书","role":"查阅"},{"i":43,"sec":"第1章 原书版课件","title":"（五）非共价相互作用对大分子的结构和功能是关键的","notes":"这一页总结四类作用的分工：离子键—电荷；氢键—方向性识别；范德华—紧密堆积；疏水—折叠驱动力。强调“弱”不是缺点，而是可逆、可调控的前提。","img":"assets/img/bc01deck/slide-44.jpg?v=20261108eg","points":["单个非共价作用弱，但数量多、可协同，形成稳定结构。","它们允许生物大分子在温和条件下组装和解离。","决定蛋白质折叠、核酸双螺旋、膜结构和分子识别。","也是酶催化、信号转导、免疫识别的基础。"],"check":{"kind":"short","id":"bc01_s44_check","q":"本页「（五）非共价相互作用对大分子的结构和功能是关键的」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：单个非共价作用弱，但数量多、可协同，形成稳定结构。；它们允许生物大分子在温和条件下组装和解离。；决定蛋白质折叠、核酸双螺旋、膜结构和分子识别。；也是酶催化、信号转导、免疫识别的基础。","e":"解析：这一页总结四类作用的分工：离子键—电荷；氢键—方向性识别；范德华—紧密堆积；疏水—折叠驱动力。强调“弱”不是缺点，而是可逆、可调控的前提。 关键点：单个非共价作用弱，但数量多、可协同，形成稳定结构。；它们允许生物大分子在温和条件下组装和解离。；决定蛋白质折叠、核酸双螺旋、膜结构和分子识别。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s44_exam","q":"关于本页「（五）非共价相互作用对大分子的结构和功能是关键的」，下列哪项表述正确？","o":["A. 自装配：亚基自发缔合成复合体，驱动力主要是疏水作用。","B. 碳原子四价，可形成四个稳定共价键。","C. 脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。","D. 单个非共价作用弱，但数量多、可协同，形成稳定结构。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（三）自我复制和自我装配是生命状态的精华」的内容，不是本页核心。","属于「（二）生物分子是碳的化合物」的内容，不是本页核心。","属于「（四）生物大分子及其单体亚基」的内容，不是本页核心。","本页要点：单个非共价作用弱，但数量多、可协同，形成稳定结构。"],"src":"期末·选择题"},"source":"老师第1章PPT 第44页","imageExplain":"这张图在讲：这一页总结四类作用的分工：离子键—电荷。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：单个非共价作用弱，但数量多、可协同，形成稳定结构。；它们允许生物大分子在温和条件下组装和解离。。","srcType":"原书","role":"查阅"},{"i":44,"sec":"第1章 原书版课件","title":"第5节 · 3句话 + 2题自测","notes":"第5节收束：四类作用“弱而多”，是生命动态性的基础。","img":"","points":["四类非共价作用：离子相互作用、氢键、范德华力、疏水作用。","单个弱、数量多、可协同；稳定三维结构并允许动态组装。","疏水作用本质是水氢键网络的熵驱动，不是“油水相吸”。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap5_1","kind":"mcq","q":"蛋白质折叠的主要驱动力常是？","o":["A. 离子键","B. 氢键","C. 疏水作用","D. 范德华力"],"a":"C","e":"非极性侧链避水聚集，疏水作用是折叠的主要驱动力。","oe":["离子键只占一部分。","氢键稳定二级结构。","正确。","范德华力贡献较小。"],"src":"本节收束"},{"id":"bc01_wrap5_2","kind":"mcq","q":"DNA碱基配对主要靠？","o":["A. 离子键","B. 氢键","C. 疏水作用","D. 二硫键"],"a":"B","e":"A=T两个氢键，G≡C三个氢键。","oe":["不是主要作用。","正确。","疏水作用参与堆积。","DNA没有二硫键。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":45,"sec":"第1章 原书版课件","title":"第5节难点：疏水作用为什么是熵驱动？","notes":"第5节难点：用“水氢键网络被破坏→水熵增”解释疏水作用。","img":"","points":["非极性基团进入水中会破坏水—水氢键，使水分子有序化。","聚集后减少疏水表面积，释放有序水分子。","水分子混乱度增加，体系熵增，自由能降低，过程自发。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break46","kind":"short","q":"为什么疏水作用常是蛋白质折叠的主要驱动力？","a":"得分点：非极性基团破坏水氢键网络→水分子有序化→聚集减少疏水表面积→水熵增→自由能降低。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":46,"sec":"第1章 原书版课件","title":"水和生命","notes":"本节导览：水有哪些特殊性质？；水为什么是生命介质？；弱酸弱碱和缓冲如何影响生物分子？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-47.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第47页","imageExplain":"这张图在讲：本节导览：水有哪些特殊性质？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":47,"sec":"第1章 原书版课件","title":"（一）水的结构和性质","notes":"把“结构—性质—功能”连起来：极性→氢键→高热容/高沸点→缓冲温度、支持生命。水的高热容是重点。","img":"assets/img/bc01deck/slide-48.jpg?v=20261108eg","points":["水是极性分子，O—H 键极性，分子间形成氢键。","每个水分子最多形成4个氢键，形成动态网络。","结果：高沸点、高熔点、高蒸发热、高热容、高表面张力。","水的高介电常数使离子化合物易溶解。"],"check":{"kind":"short","id":"bc01_s48_check","q":"本页「（一）水的结构和性质」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：水是极性分子，O—H 键极性，分子间形成氢键。；每个水分子最多形成4个氢键，形成动态网络。；结果：高沸点、高熔点、高蒸发热、高热容、高表面张力。；水的高介电常数使离子化合物易溶解。","e":"解析：把“结构—性质—功能”连起来：极性→氢键→高热容/高沸点→缓冲温度、支持生命。水的高热容是重点。 关键点：水是极性分子，O—H 键极性，分子间形成氢键。；每个水分子最多形成4个氢键，形成动态网络。；结果：高沸点、高熔点、高蒸发热、高热容、高表面张力。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s48_exam","q":"关于本页「（一）水的结构和性质」，下列哪项表述正确？","o":["A. 生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。","B. 酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。","C. 也是酶催化、信号转导、免疫识别的基础。","D. 水是极性分子，O—H 键极性，分子间形成氢键。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）生物分子的大小」的内容，不是本页核心。","属于「（六）生物分子间的相互作用是立体专一的」的内容，不是本页核心。","属于「（五）非共价相互作用对大分子的结构和功能是关键的」的内容，不是本页核心。","本页要点：水是极性分子，O—H 键极性，分子间形成氢键。"],"src":"期末·选择题"},"source":"老师第1章PPT 第48页","imageExplain":"这张图在讲：把“结构—性质—功能”连起来：极性→氢键→高热容/高沸点→缓冲温度、支持生命。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：水是极性分子，O—H 键极性，分子间形成氢键。；每个水分子最多形成4个氢键，形成动态网络。。","srcType":"原书","role":"查阅"},{"i":48,"sec":"第1章 原书版课件","title":"图1-12 水分子结构与冰中氢键","notes":"图1-12分A、B、C三部分：先看水分子的极性，再看四面体氢键，最后看冰的三维网络。不要把B的四面体簇和C的六元环混为一谈。","img":"assets/img/bc01deck/slide-49.jpg?v=20261108eg","points":["A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。","B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。","C：水分子通过氢键连成三维网络，可看出六元环排列。","氢键网络解释水的高热容、高沸点、高表面张力。"],"imageExplain":"本页为原书配图：图1-12 水分子结构与冰中氢键。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s49_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。；B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。；C：水分子通过氢键连成三维网络，可看出六元环排列。；氢键网络解释水的高热容、高沸点、高表面张力。","e":"解析：图1-12分A、B、C三部分：先看水分子的极性，再看四面体氢键，最后看冰的三维网络。不要把B的四面体簇和C的六元环混为一谈。 关键点：A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。；B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。；C：水分子通过氢键连成三维网络，可看出六元环排列。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s49_exam","q":"关于本页「图1-12 水分子结构与冰中氢键」，下列哪项表述正确？","o":["A. A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。","B. 构象：同一构型下，通过单键旋转产生的不同空间形态。","C. 蛋白质二级结构：α螺旋、β折叠靠主链氢键稳定。","D. 水参与水解、水合、氧化还原等反应。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。","属于「（四）构象」的内容，不是本页核心。","属于「（二）氢键」的内容，不是本页核心。","属于「（二）水是生命的介质」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第49页","srcType":"原书","role":"查阅"},{"i":49,"sec":"第1章 原书版课件","title":"（二）水是生命的介质","notes":"水不是惰性背景，而是积极参与生命过程。强调“介质+反应物+温度缓冲”三重角色。","img":"assets/img/bc01deck/slide-50.jpg?v=20261108eg","points":["水占细胞质量的大部分，是物质运输和反应的介质。","极性分子、离子易溶于水；非极性分子难溶。","水参与水解、水合、氧化还原等反应。","水的流动性支持扩散、渗透和胞内运输。"],"check":{"kind":"short","id":"bc01_s50_check","q":"本页「（二）水是生命的介质」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：水占细胞质量的大部分，是物质运输和反应的介质。；极性分子、离子易溶于水；非极性分子难溶。；水参与水解、水合、氧化还原等反应。；水的流动性支持扩散、渗透和胞内运输。","e":"解析：水不是惰性背景，而是积极参与生命过程。强调“介质+反应物+温度缓冲”三重角色。 关键点：水占细胞质量的大部分，是物质运输和反应的介质。；极性分子、离子易溶于水；非极性分子难溶。；水参与水解、水合、氧化还原等反应。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s50_exam","q":"关于本页「（二）水是生命的介质」，下列哪项表述正确？","o":["A. 手性碳连四个不同基团；对映体互为镜像、不能重合。","B. 水占细胞质量的大部分，是物质运输和反应的介质。","C. 聚集后减少疏水表面积，释放有序水分子。","D. 细菌和古菌是原核生物，无核膜包被的细胞核。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第4节 · 3句话 + 2题自测」的内容，不是本页核心。","本页要点：水占细胞质量的大部分，是物质运输和反应的介质。","属于「第5节难点：疏水作用为什么是熵驱动？」的内容，不是本页核心。","属于「（一）生物三域——细菌、古菌和真核生物」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第50页","imageExplain":"这张图在讲：水不是惰性背景，而是积极参与生命过程。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：水占细胞质量的大部分，是物质运输和反应的介质。；极性分子、离子易溶于水；非极性分子难溶。。","srcType":"原书","role":"查阅"},{"i":50,"sec":"第1章 原书版课件","title":"（三）溶质影响水的依数性","notes":"依数性只数“粒子数”，不数“粒子种类”。联系医学：输液必须考虑渗透压；细胞在低渗溶液中吸水胀破，在高渗溶液中皱缩。","img":"assets/img/bc01deck/slide-51.jpg?v=20261108eg","points":["依数性：只与溶质粒子数有关，与粒子性质关系较小。","包括蒸汽压下降、沸点升高、凝固点降低、渗透压。","渗透压对细胞体积、水分分布至关重要。","生物体通过渗透调节维持细胞内外水平衡。"],"check":{"kind":"short","id":"bc01_s51_check","q":"本页「（三）溶质影响水的依数性」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：依数性：只与溶质粒子数有关，与粒子性质关系较小。；包括蒸汽压下降、沸点升高、凝固点降低、渗透压。；渗透压对细胞体积、水分分布至关重要。；生物体通过渗透调节维持细胞内外水平衡。","e":"解析：依数性只数“粒子数”，不数“粒子种类”。联系医学：输液必须考虑渗透压；细胞在低渗溶液中吸水胀破，在高渗溶液中皱缩。 关键点：依数性：只与溶质粒子数有关，与粒子性质关系较小。；包括蒸汽压下降、沸点升高、凝固点降低、渗透压。；渗透压对细胞体积、水分分布至关重要。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s51_exam","q":"关于本页「（三）溶质影响水的依数性」，下列哪项表述正确？","o":["A. 非极性基团在水中有避水聚集的倾向。","B. 细胞核：遗传信息储存、转录场所。","C. 依数性：只与溶质粒子数有关，与粒子性质关系较小。","D. 原始细胞能摄取物质、进行反应、复制遗传信息。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）疏水相互作用」的内容，不是本页核心。","属于「（四）真核细胞含有多种膜性细胞器」的内容，不是本页核心。","本页要点：依数性：只与溶质粒子数有关，与粒子性质关系较小。","属于「（三）原始细胞的出现——生物学进化的开始」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第51页","imageExplain":"这张图在讲：依数性只数“粒子数”，不数“粒子种类”。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：依数性：只与溶质粒子数有关，与粒子性质关系较小。；包括蒸汽压下降、沸点升高、凝固点降低、渗透压。。","srcType":"原书","role":"查阅"},{"i":51,"sec":"第1章 原书版课件","title":"（四）水、弱酸和弱碱的电离","notes":"这一页是计算题基础。强调pH、pKa、缓冲范围三者关系；缓冲液在pKa±1范围内最有效。等电点pI是蛋白质/氨基酸净电荷为零的pH。","img":"assets/img/bc01deck/slide-52.jpg?v=20261108eg","points":["水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。","弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。","Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。","当[A⁻]=[HA]时，pH = pKa；此时缓冲能力较强。"],"check":{"kind":"short","id":"bc01_s52_check","q":"本页「（四）水、弱酸和弱碱的电离」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。；弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。；Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。；当[A⁻]=[HA]时，pH = pKa；此时缓冲能力较强。","e":"解析：这一页是计算题基础。强调pH、pKa、缓冲范围三者关系；缓冲液在pKa±1范围内最有效。等电点pI是蛋白质/氨基酸净电荷为零的pH。 关键点：水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。；弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。；Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s52_exam","q":"关于本页「（四）水、弱酸和弱碱的电离」，下列哪项表述正确？","o":["A. 水的高介电常数使离子化合物易溶解。","B. 细菌、古菌为原核生物；真核生物有核膜和细胞器。","C. 大肠杆菌（70S核糖体、质粒、鞭毛）；酵母/植物/动物细胞。","D. 水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）水的结构和性质」的内容，不是本页核心。","属于「图1-15 生物三域系统树」的内容，不是本页核心。","属于「第7节难点：原核与真核怎么比？」的内容，不是本页核心。","本页要点：水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。"],"src":"期末·选择题"},"source":"老师第1章PPT 第52页","imageExplain":"这张图在讲：强调pH、pKa、缓冲范围三者关系。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。；弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。。","srcType":"原书","role":"查阅"},{"i":52,"sec":"第1章 原书版课件","title":"第6节 · 3句话 + 2题自测","notes":"第6节收束：水结构→性质→渗透/酸碱，计算题也在这里落地。","img":"","points":["水是极性分子，氢键网络带来高热容、高沸点、高表面张力。","水是溶剂、反应物/产物和温度缓冲介质；溶质影响依数性。","pH=−lg[H⁺]；缓冲液用 pH=pKa+lg([A⁻]/[HA])；等电点时净电荷为零。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap6_1","kind":"mcq","q":"水具有高热容的主要原因是？","o":["A. 分子很小","B. 分子间大量氢键","C. 不含碳","D. 中性分子"],"a":"B","e":"氢键网络吸收热量，使水温升高需要更多能量。","oe":["分子小不是原因。","正确。","含碳与否无关。","中性不是原因。"],"src":"本节收束"},{"id":"bc01_wrap6_2","kind":"mcq","q":"缓冲液中[A⁻]=[HA]时，pH等于？","o":["A. pKa","B. 7.0","C. pI","D. 0"],"a":"A","e":"Henderson-Hasselbalch：pH=pKa+lg([A⁻]/[HA])，比值为1时pH=pKa。","oe":["正确。","7.0只在中性附近。","pI是等电点。","pH0是强酸。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":53,"sec":"第1章 原书版课件","title":"第6节难点：缓冲液计算三步走","notes":"第6节难点：缓冲液计算固定三步：方程—比值—总浓度。","img":"","points":["pH = pKa + lg([A⁻]/[HA])；[A⁻]=盐，[HA]=酸。","先算比值 r=10^(pH−pKa)，再结合总浓度 x+y=C。","x=盐浓度，y=酸浓度；检查单位与比例。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break54","kind":"short","q":"写出缓冲液计算的三步，并说明各符号。","a":"得分点：pH=pKa+lg([A⁻]/[HA])；r=10^(pH−pKa)=盐/酸；x+y=C；[A⁻]=盐，[HA]=酸。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":54,"sec":"第1章 原书版课件","title":"生命的基本单位——细胞","notes":"本节导览：生物三域如何划分？；为什么细胞是生命的基本单位？；原核细胞与真核细胞有何区别？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-55.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第55页","imageExplain":"这张图在讲：本节导览：生物三域如何划分？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":55,"sec":"第1章 原书版课件","title":"（一）生物三域——细菌、古菌和真核生物","notes":"三域不是“细菌、植物、动物”，而是细菌、古菌、真核。古菌常被误认为细菌，要强调其分子特征和极端环境适应性。","img":"assets/img/bc01deck/slide-56.jpg?v=20261108eg","points":["三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。","细菌和古菌是原核生物，无核膜包被的细胞核。","古菌在分子特征上更接近真核生物，常生活在极端环境。","真核生物有核膜、细胞核和多种膜性细胞器。"],"check":{"kind":"short","id":"bc01_s56_check","q":"本页「（一）生物三域——细菌、古菌和真核生物」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。；细菌和古菌是原核生物，无核膜包被的细胞核。；古菌在分子特征上更接近真核生物，常生活在极端环境。；真核生物有核膜、细胞核和多种膜性细胞器。","e":"解析：三域不是“细菌、植物、动物”，而是细菌、古菌、真核。古菌常被误认为细菌，要强调其分子特征和极端环境适应性。 关键点：三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。；细菌和古菌是原核生物，无核膜包被的细胞核。；古菌在分子特征上更接近真核生物，常生活在极端环境。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s56_exam","q":"关于本页「（一）生物三域——细菌、古菌和真核生物」，下列哪项表述正确？","o":["A. 生物大分子聚集成膜包被的原始细胞（protocell）。","B. 自制教学课件 · 非老师原PPT","C. Pasteur、Fischer、Hopkins、Pavlov、Sumner 等推动微生物学、结构化学、维生素、消化生理与酶化学。","D. 三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（三）原始细胞的出现——生物学进化的开始」的内容，不是本页核心。","属于「生命的分子基础」的内容，不是本页核心。","属于「（二）现代生物化学发展中的一些重要学术中心和学者」的内容，不是本页核心。","本页要点：三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。"],"src":"期末·选择题"},"source":"老师第1章PPT 第56页","imageExplain":"这张图在讲：三域不是“细菌、植物、动物”，而是细菌、古菌、真核。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。；细菌和古菌是原核生物，无核膜包被的细胞核。。","srcType":"原书","role":"查阅"},{"i":56,"sec":"第1章 原书版课件","title":"图1-15 生物三域系统树","notes":"图1-15是无根扇状树。读图先找三个域标签，再看各域包含的类群；分支长短表示差异，不表示进化等级。","img":"assets/img/bc01deck/slide-57.jpg?v=20261108eg","points":["系统树基于 rRNA 序列相似性：序列越相似，分支越接近。","三域：细菌域、古菌域、真核生物域，共同祖先在树底部。","细菌、古菌为原核生物；真核生物有核膜和细胞器。","分支距离表示序列差异程度，不表示“谁更高级”。"],"imageExplain":"本页为原书配图：图1-15 生物三域系统树。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s57_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：系统树基于 rRNA 序列相似性：序列越相似，分支越接近。；三域：细菌域、古菌域、真核生物域，共同祖先在树底部。；细菌、古菌为原核生物；真核生物有核膜和细胞器。；分支距离表示序列差异程度，不表示“谁更高级”。","e":"解析：图1-15是无根扇状树。读图先找三个域标签，再看各域包含的类群；分支长短表示差异，不表示进化等级。 关键点：系统树基于 rRNA 序列相似性：序列越相似，分支越接近。；三域：细菌域、古菌域、真核生物域，共同祖先在树底部。；细菌、古菌为原核生物；真核生物有核膜和细胞器。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s57_exam","q":"关于本页「图1-15 生物三域系统树」，下列哪项表述正确？","o":["A. 系统树基于 rRNA 序列相似性：序列越相似，分支越接近。","B. A. C B. H C. Fe D. O","C. 单体通过共价键聚合成生物大分子，更高层次靠非共价作用组装。","D. 常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：系统树基于 rRNA 序列相似性：序列越相似，分支越接近。","属于「5 道题检查本章掌握度」的内容，不是本页核心。","属于「第1节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「（二）生物分子是碳的化合物」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第57页","srcType":"原书","role":"查阅"},{"i":57,"sec":"第1章 原书版课件","title":"（二）细胞是所有生物的结构和功能单位","notes":"从“边界、代谢、遗传、繁殖”四个角度说明细胞为什么是基本单位。表面积/体积比解释为什么细胞不能无限大。","img":"assets/img/bc01deck/slide-58.jpg?v=20261108eg","points":["细胞是生命结构和功能的基本单位。","单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。","细胞膜界定边界，维持内环境相对稳定。","细胞体积小，有利于物质交换；表面积/体积比是关键。"],"check":{"kind":"short","id":"bc01_s58_check","q":"本页「（二）细胞是所有生物的结构和功能单位」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：细胞是生命结构和功能的基本单位。；单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。；细胞膜界定边界，维持内环境相对稳定。；细胞体积小，有利于物质交换；表面积/体积比是关键。","e":"解析：从“边界、代谢、遗传、繁殖”四个角度说明细胞为什么是基本单位。表面积/体积比解释为什么细胞不能无限大。 关键点：细胞是生命结构和功能的基本单位。；单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。；细胞膜界定边界，维持内环境相对稳定。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s58_exam","q":"关于本页「（二）细胞是所有生物的结构和功能单位」，下列哪项表述正确？","o":["A. 蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。","B. 细胞是生命结构和功能的基本单位。","C. 现代生物化学大体经历静态、动态、分子三个阶段。","D. 重点认羟基、羰基、羧基、酯基、磷酸基。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）化学成分复杂而同一、结构错综而有序」的内容，不是本页核心。","本页要点：细胞是生命结构和功能的基本单位。","属于「第2节 · 3句话 + 2题自测」的内容，不是本页核心。","属于「图1-3 局部放大（上）：含氧官能团」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第58页","imageExplain":"这张图在讲：从“边界、代谢、遗传、繁殖”四个角度说明细胞为什么是基本单位。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：细胞是生命结构和功能的基本单位。；单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。。","srcType":"原书","role":"查阅"},{"i":58,"sec":"第1章 原书版课件","title":"（三）原核细胞的代表——大肠杆菌","notes":"以大肠杆菌为原核代表，记住“无核膜、拟核、70S核糖体、环状DNA、质粒”。这些也是抗生素作用靶点的背景。","img":"assets/img/bc01deck/slide-59.jpg?v=20261108eg","points":["大肠杆菌：革兰氏阴性、杆状、无核膜。","遗传物质：环状DNA，位于拟核；可有质粒。","核糖体：70S（50S+30S），是蛋白质合成场所。","细胞膜外有细胞壁；部分菌株有鞭毛、菌毛。"],"check":{"kind":"short","id":"bc01_s59_check","q":"本页「（三）原核细胞的代表——大肠杆菌」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：大肠杆菌：革兰氏阴性、杆状、无核膜。；遗传物质：环状DNA，位于拟核；可有质粒。；核糖体：70S（50S+30S），是蛋白质合成场所。；细胞膜外有细胞壁；部分菌株有鞭毛、菌毛。","e":"解析：以大肠杆菌为原核代表，记住“无核膜、拟核、70S核糖体、环状DNA、质粒”。这些也是抗生素作用靶点的背景。 关键点：大肠杆菌：革兰氏阴性、杆状、无核膜。；遗传物质：环状DNA，位于拟核；可有质粒。；核糖体：70S（50S+30S），是蛋白质合成场所。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s59_exam","q":"关于本页「（三）原核细胞的代表——大肠杆菌」，下列哪项表述正确？","o":["A. 第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。","B. 生物分子以碳骨架为基础，但三键在生物分子中较少见。","C. 大肠杆菌：革兰氏阴性、杆状、无核膜。","D. 小分子：相对分子质量几十到几百；生物大分子：通常 >5000。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）现代生物化学的发展和分子生物学的兴起」的内容，不是本页核心。","属于「图1-1 碳原子成键的多能性」的内容，不是本页核心。","本页要点：大肠杆菌：革兰氏阴性、杆状、无核膜。","属于「（一）生物分子的大小」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第59页","imageExplain":"这张图在讲：以大肠杆菌为原核代表，记住“无核膜、拟核、70S核糖体、环状DNA、质粒”。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：大肠杆菌：革兰氏阴性、杆状、无核膜。；遗传物质：环状DNA，位于拟核；可有质粒。。","srcType":"原书","role":"查阅"},{"i":59,"sec":"第1章 原书版课件","title":"图1-16 细菌细胞（以大肠杆菌为代表）","notes":"图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物。左下放大框专门讲被膜三层。","img":"assets/img/bc01deck/slide-60.jpg?v=20261108eg","points":["图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物","左下放大框专门讲被膜三层"],"check":{"kind":"short","id":"bc01_s60_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物；左下放大框专门讲被膜三层","e":"解析：图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物。左下放大框专门讲被膜三层。 关键点：图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物；左下放大框专门讲被膜三层","src":"本页自测"},"imageExplain":"本页为原书配图：图1-16 细菌细胞（以大肠杆菌为代表）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s60_exam","q":"关于本页「图1-16 细菌细胞（以大肠杆菌为代表）」，下列哪项表述正确？","o":["A. 吴宪、牛胰岛素、tRNA人工合成。","B. 磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。","C. 中央竖线为镜面，左右两组互为镜像，不能重合。","D. 图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第2节难点：三阶段怎么记？」的内容，不是本页核心。","属于「图1-3 局部放大（下）：含氮/含硫/含磷官能团」的内容，不是本页核心。","属于「图1-5 甘油醛的构型（D/L 命名系统）」的内容，不是本页核心。","本页要点：图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物"],"src":"期末·选择题"},"source":"老师第1章PPT 第60页","srcType":"原书","role":"查阅"},{"i":60,"sec":"第1章 原书版课件","title":"（四）真核细胞含有多种膜性细胞器","notes":"按“遗传信息—能量—合成加工—运输降解”讲细胞器，避免孤立记忆。线粒体和叶绿体有自身DNA，为内共生起源提供证据。","img":"assets/img/bc01deck/slide-61.jpg?v=20261108eg","points":["细胞核：遗传信息储存、转录场所。","线粒体：氧化磷酸化、ATP合成；有自身DNA。","内质网：蛋白质/脂质合成与加工；粗面ER有核糖体。","高尔基体：加工、分选和运输；溶酶体：降解。"],"check":{"kind":"short","id":"bc01_s61_check","q":"本页「（四）真核细胞含有多种膜性细胞器」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：细胞核：遗传信息储存、转录场所。；线粒体：氧化磷酸化、ATP合成；有自身DNA。；内质网：蛋白质/脂质合成与加工；粗面ER有核糖体。；高尔基体：加工、分选和运输；溶酶体：降解。","e":"解析：按“遗传信息—能量—合成加工—运输降解”讲细胞器，避免孤立记忆。线粒体和叶绿体有自身DNA，为内共生起源提供证据。 关键点：细胞核：遗传信息储存、转录场所。；线粒体：氧化磷酸化、ATP合成；有自身DNA。；内质网：蛋白质/脂质合成与加工；粗面ER有核糖体。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s61_exam","q":"关于本页「（四）真核细胞含有多种膜性细胞器」，下列哪项表述正确？","o":["A. 细胞核：遗传信息储存、转录场所。","B. 生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。","C. 立体异构：连接次序相同，空间排列不同。","D. 手性识别是生物专一性的基础：对映体生物活性常不同。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：细胞核：遗传信息储存、转录场所。","属于「（三）生物小分子与代谢物」的内容，不是本页核心。","属于「（二）立体异构与构型」的内容，不是本页核心。","属于「（六）生物分子间的相互作用是立体专一的」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第61页","imageExplain":"这张图在讲：按“遗传信息—能量—合成加工—运输降解”讲细胞器，避免孤立记忆。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：细胞核：遗传信息储存、转录场所。；线粒体：氧化磷酸化、ATP合成；有自身DNA。。","srcType":"原书","role":"查阅"},{"i":61,"sec":"第1章 原书版课件","title":"图1-17 真核细胞结构模式图","notes":"图1-17是动物细胞与植物细胞并排。先比较细胞壁、液泡、叶绿体三项差异，再在两类细胞中找共同细胞器。","img":"assets/img/bc01deck/slide-62.jpg?v=20261108eg","points":["左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。","右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。","叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。","真核细胞有核膜和多种膜性细胞器；动物/植物细胞结构有差异。"],"imageExplain":"本页为原书配图：图1-17 真核细胞结构模式图。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","check":{"kind":"short","id":"bc01_s62_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。；右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。；叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。；真核细胞有核膜和多种膜性细胞器；动物/植物细胞结构有差异。","e":"解析：图1-17是动物细胞与植物细胞并排。先比较细胞壁、液泡、叶绿体三项差异，再在两类细胞中找共同细胞器。 关键点：左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。；右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。；叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s62_exam","q":"关于本页「图1-17 真核细胞结构模式图」，下列哪项表述正确？","o":["A. 脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。","B. 左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。","C. 例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。","D. 包括取向力、诱导力、色散力；色散力最普遍。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）生物大分子及其单体亚基」的内容，不是本页核心。","本页要点：左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。","属于「（四）构象」的内容，不是本页核心。","属于「（三）范德华力」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第62页","srcType":"原书","role":"查阅"},{"i":62,"sec":"第1章 原书版课件","title":"第7节 · 3句话 + 2题自测","notes":"第7节收束：三域→细胞单位→原核代表→真核细胞器。","img":"","points":["三域：细菌、古菌、真核；前两者为原核，无核膜。","细胞是结构与功能基本单位；原核有拟核、70S核糖体、质粒。","真核有核膜和膜性细胞器；植物细胞还有细胞壁、液泡、叶绿体。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap7_1","kind":"mcq","q":"原核细胞与真核细胞的主要区别是？","o":["A. 有无DNA","B. 有无核膜","C. 有无核糖体","D. 有无细胞膜"],"a":"B","e":"原核无核膜包被的细胞核；两者都有DNA、核糖体和细胞膜。","oe":["两者都有DNA。","正确。","两者都有核糖体。","两者都有细胞膜。"],"src":"本节收束"},{"id":"bc01_wrap7_2","kind":"mcq","q":"大肠杆菌的核糖体是？","o":["A. 80S","B. 70S","C. 60S","D. 40S"],"a":"B","e":"大肠杆菌核糖体为70S（50S+30S）。","oe":["80S是真核核糖体。","正确。","60S是大小亚基之一。","40S是真核小亚基。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":63,"sec":"第1章 原书版课件","title":"图1-17 局部放大：动物细胞","notes":"图1-17左半局部：动物细胞。先找细胞核，再找线粒体、内质网、高尔基体、溶酶体。","img":"assets/img/bc01deck/slide-64.jpg?v=20261108eg","points":["图1-17左半局部：动物细胞","先找细胞核，再找线粒体、内质网、高尔基体、溶酶体"],"check":{"kind":"short","id":"bc01_s64_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-17左半局部：动物细胞；先找细胞核，再找线粒体、内质网、高尔基体、溶酶体","e":"解析：图1-17左半局部：动物细胞。先找细胞核，再找线粒体、内质网、高尔基体、溶酶体。 关键点：图1-17左半局部：动物细胞；先找细胞核，再找线粒体、内质网、高尔基体、溶酶体","src":"本页自测"},"imageExplain":"本页为原书配图：图1-17 局部放大：动物细胞。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s64_exam","q":"关于本页「图1-17 局部放大：动物细胞」，下列哪项表述正确？","o":["A. X射线晶体学、NMR、冷冻电镜是主要结构测定方法。","B. 蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。","C. 弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。","D. 图1-17左半局部：动物细胞"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（五）三维结构的分子模型」的内容，不是本页核心。","属于「（四）疏水相互作用」的内容，不是本页核心。","属于「（四）水、弱酸和弱碱的电离」的内容，不是本页核心。","本页要点：图1-17左半局部：动物细胞"],"src":"期末·选择题"},"source":"老师第1章PPT 第64页","srcType":"原书","role":"查阅"},{"i":64,"sec":"第1章 原书版课件","title":"图1-17 局部放大：植物细胞","notes":"图1-17右半局部：植物细胞。重点比较细胞壁、液泡、叶绿体与动物细胞的差异。","img":"assets/img/bc01deck/slide-65.jpg?v=20261108eg","points":["图1-17右半局部：植物细胞","重点比较细胞壁、液泡、叶绿体与动物细胞的差异"],"check":{"kind":"short","id":"bc01_s65_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-17右半局部：植物细胞；重点比较细胞壁、液泡、叶绿体与动物细胞的差异","e":"解析：图1-17右半局部：植物细胞。重点比较细胞壁、液泡、叶绿体与动物细胞的差异。 关键点：图1-17右半局部：植物细胞；重点比较细胞壁、液泡、叶绿体与动物细胞的差异","src":"本页自测"},"imageExplain":"本页为原书配图：图1-17 局部放大：植物细胞。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s65_exam","q":"关于本页「图1-17 局部放大：植物细胞」，下列哪项表述正确？","o":["A. 图1-17右半局部：植物细胞","B. DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。","C. B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。","D. 细胞是生命结构和功能的基本单位。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：图1-17右半局部：植物细胞","属于「（一）离子相互作用」的内容，不是本页核心。","属于「图1-12 水分子结构与冰中氢键」的内容，不是本页核心。","属于「（二）细胞是所有生物的结构和功能单位」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第65页","srcType":"原书","role":"查阅"},{"i":65,"sec":"第1章 原书版课件","title":"第7节难点：原核与真核怎么比？","notes":"第7节难点：用五项对比表区分原核/真核，不要只记“有没有核”。","img":"","points":["原核无核膜，DNA在拟核；真核有核膜包被的细胞核。","原核只有核糖体；真核有线粒体、内质网、高尔基体、溶酶体等。","大肠杆菌（70S核糖体、质粒、鞭毛）；酵母/植物/动物细胞。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break66","kind":"short","q":"用五项对比原核细胞与真核细胞。","a":"得分点：核膜（无/有）、细胞器（少/多）、DNA组织（拟核/核）、核糖体（70S/80S）、代表（大肠杆菌/酵母等）。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":66,"sec":"第1章 原书版课件","title":"生物分子的起源与进化","notes":"本节导览：生物分子如何通过化学进化产生？；为什么说RNA可能是最早的基因和催化剂？；真核细胞如何从原核细胞进化而来？。先带着这些问题看后面逐页内容。","img":"assets/img/bc01deck/slide-67.jpg?v=20261108eg","points":[],"source":"老师第1章PPT 第67页","imageExplain":"这张图在讲：本节导览：生物分子如何通过化学进化产生？。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：图的主体和标注。","srcType":"原书","role":"查阅"},{"i":67,"sec":"第1章 原书版课件","title":"（一）最初的生物分子是通过化学进化产生的","notes":"区分“化学进化”和“生物进化”：前者是无机到有机、小分子到大分子；后者是细胞出现后的繁殖、变异和选择。米勒实验是经典证据，但不是生命起源的完整答案。","img":"assets/img/bc01deck/slide-68.jpg?v=20261108eg","points":["早期地球：还原性大气、强紫外线、雷电、火山活动。","无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。","米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。","有机小分子在合适条件下聚合为生物大分子。"],"check":{"kind":"short","id":"bc01_s68_check","q":"本页「（一）最初的生物分子是通过化学进化产生的」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：早期地球：还原性大气、强紫外线、雷电、火山活动。；无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。；米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。；有机小分子在合适条件下聚合为生物大分子。","e":"解析：区分“化学进化”和“生物进化”：前者是无机到有机、小分子到大分子；后者是细胞出现后的繁殖、变异和选择。米勒实验是经典证据，但不是生命起源的完整答案。 关键点：早期地球：还原性大气、强紫外线、雷电、火山活动。；无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。；米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s68_exam","q":"关于本页「（一）最初的生物分子是通过化学进化产生的」，下列哪项表述正确？","o":["A. 细菌和古菌是原核生物，无核膜包被的细胞核。","B. 先找细胞核，再找线粒体、内质网、高尔基体、溶酶体","C. DNA接管贮存，蛋白质接管催化，原始细胞出现。","D. 早期地球：还原性大气、强紫外线、雷电、火山活动。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（一）生物三域——细菌、古菌和真核生物」的内容，不是本页核心。","属于「图1-17 局部放大：动物细胞」的内容，不是本页核心。","属于「第8节难点：RNA世界与内共生」的内容，不是本页核心。","本页要点：早期地球：还原性大气、强紫外线、雷电、火山活动。"],"src":"期末·选择题"},"source":"老师第1章PPT 第68页","imageExplain":"这张图在讲：区分“化学进化”和“生物进化”：前者是无机到有机、小分子到大分子。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：早期地球：还原性大气、强紫外线、雷电、火山活动。；无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。。","srcType":"原书","role":"查阅"},{"i":68,"sec":"第1章 原书版课件","title":"（二）RNA或相关前体可能是最早的基因和催化剂","notes":"RNA世界的核心逻辑：信息+催化双重功能，解决“先有DNA还是先有蛋白质”的循环。核酶是支持证据；要说明这是假说，不是定论。","img":"assets/img/bc01deck/slide-69.jpg?v=20261108eg","points":["RNA既能贮存遗传信息，又能催化反应（核酶）。","“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。","核酶的存在说明“核酸只是信息分子”不成立。","后来DNA更适合长期贮存信息，蛋白质催化效率更高。"],"check":{"kind":"short","id":"bc01_s69_check","q":"本页「（二）RNA或相关前体可能是最早的基因和催化剂」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：RNA既能贮存遗传信息，又能催化反应（核酶）。；“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。；核酶的存在说明“核酸只是信息分子”不成立。；后来DNA更适合长期贮存信息，蛋白质催化效率更高。","e":"解析：RNA世界的核心逻辑：信息+催化双重功能，解决“先有DNA还是先有蛋白质”的循环。核酶是支持证据；要说明这是假说，不是定论。 关键点：RNA既能贮存遗传信息，又能催化反应（核酶）。；“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。；核酶的存在说明“核酸只是信息分子”不成立。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s69_exam","q":"关于本页「（二）RNA或相关前体可能是最早的基因和催化剂」，下列哪项表述正确？","o":["A. RNA既能贮存遗传信息，又能催化反应（核酶）。","B. 细胞核：遗传信息储存、转录场所。","C. 原始细胞能摄取物质、进行反应、复制遗传信息。","D. 8节、33个子节：先框架，后细节。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：RNA既能贮存遗传信息，又能催化反应（核酶）。","属于「（四）真核细胞含有多种膜性细胞器」的内容，不是本页核心。","属于「（三）原始细胞的出现——生物学进化的开始」的内容，不是本页核心。","属于「第1章 生命的分子基础 · 8 节 33 个子节」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第69页","imageExplain":"这张图在讲：RNA世界的核心逻辑：信息+催化双重功能，解决“先有DNA还是先有蛋白质”的循环。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：RNA既能贮存遗传信息，又能催化反应（核酶）。；“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。。","srcType":"原书","role":"查阅"},{"i":69,"sec":"第1章 原书版课件","title":"图1-19 “RNA世界”说的分子进化情景","notes":"图1-19是8步流程图。抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化。","img":"assets/img/bc01deck/slide-70.jpg?v=20261108eg","points":["图1-19是8步流程图","抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化"],"check":{"kind":"short","id":"bc01_s70_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-19是8步流程图；抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化","e":"解析：图1-19是8步流程图。抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化。 关键点：图1-19是8步流程图；抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化","src":"本页自测"},"imageExplain":"本页为原书配图：图1-19 “RNA世界”说的分子进化情景。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s70_exam","q":"关于本页「图1-19 “RNA世界”说的分子进化情景」，下列哪项表述正确？","o":["A. 大肠杆菌（70S核糖体、质粒、鞭毛）；酵母/植物/动物细胞。","B. 图1-19是8步流程图","C. A. 结构异构 B. 构型改变 C. 构象改变 D. 共价键断裂","D. ① 化学成分与结构有序；② 能量与物质自我更新；③ 自我复制与自我装配。"],"a":"B","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「第7节难点：原核与真核怎么比？」的内容，不是本页核心。","本页要点：图1-19是8步流程图","属于「5 道题检查本章掌握度」的内容，不是本页核心。","属于「第1节难点：生命属性怎么答？」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第70页","srcType":"原书","role":"查阅"},{"i":70,"sec":"第1章 原书版课件","title":"（三）原始细胞的出现——生物学进化的开始","notes":"强调“边界”的意义：没有膜，分子扩散稀释，无法形成稳定的选择单位。原始细胞不必很复杂，关键是能自我维持和复制。","img":"assets/img/bc01deck/slide-71.jpg?v=20261108eg","points":["生物大分子聚集成膜包被的原始细胞（protocell）。","膜将内部环境与外界分隔，形成相对独立的化学系统。","原始细胞能摄取物质、进行反应、复制遗传信息。","自然选择开始作用于可复制的原始细胞。"],"check":{"kind":"short","id":"bc01_s71_check","q":"本页「（三）原始细胞的出现——生物学进化的开始」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：生物大分子聚集成膜包被的原始细胞（protocell）。；膜将内部环境与外界分隔，形成相对独立的化学系统。；原始细胞能摄取物质、进行反应、复制遗传信息。；自然选择开始作用于可复制的原始细胞。","e":"解析：强调“边界”的意义：没有膜，分子扩散稀释，无法形成稳定的选择单位。原始细胞不必很复杂，关键是能自我维持和复制。 关键点：生物大分子聚集成膜包被的原始细胞（protocell）。；膜将内部环境与外界分隔，形成相对独立的化学系统。；原始细胞能摄取物质、进行反应、复制遗传信息。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s71_exam","q":"关于本页「（三）原始细胞的出现——生物学进化的开始」，下列哪项表述正确？","o":["A. 细胞核、内膜系统、细胞骨架逐渐形成。","B. 结构层次：单体亚基 → 大分子 → 超分子复合体 → 细胞器 → 细胞。","C. 生物大分子聚集成膜包被的原始细胞（protocell）。","D. 中国学者在蛋白质变性、牛胰岛素与 tRNA 人工合成等方面作出重要贡献。"],"a":"C","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「（四）真核细胞是从原核细胞进化而来的」的内容，不是本页核心。","属于「（一）化学成分复杂而同一、结构错综而有序」的内容，不是本页核心。","本页要点：生物大分子聚集成膜包被的原始细胞（protocell）。","属于「第2节 · 3句话 + 2题自测」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第71页","imageExplain":"这张图在讲：强调“边界”的意义：没有膜，分子扩散稀释，无法形成稳定的选择单位。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：生物大分子聚集成膜包被的原始细胞（protocell）。；膜将内部环境与外界分隔，形成相对独立的化学系统。。","srcType":"原书","role":"查阅"},{"i":71,"sec":"第1章 原书版课件","title":"（四）真核细胞是从原核细胞进化而来的","notes":"内共生学说是重点：线粒体/叶绿体有自身环状DNA、70S核糖体、双层膜，支持其细菌起源。不要把“内共生”误解为“细胞吞了一个细胞器”。","img":"assets/img/bc01deck/slide-72.jpg?v=20261108eg","points":["内共生学说：线粒体源于被吞入的需氧细菌。","叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。","真核细胞获得高效产能和光合作用能力。","细胞核、内膜系统、细胞骨架逐渐形成。"],"check":{"kind":"short","id":"bc01_s72_check","q":"本页「（四）真核细胞是从原核细胞进化而来的」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：内共生学说：线粒体源于被吞入的需氧细菌。；叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。；真核细胞获得高效产能和光合作用能力。；细胞核、内膜系统、细胞骨架逐渐形成。","e":"解析：内共生学说是重点：线粒体/叶绿体有自身环状DNA、70S核糖体、双层膜，支持其细菌起源。不要把“内共生”误解为“细胞吞了一个细胞器”。 关键点：内共生学说：线粒体源于被吞入的需氧细菌。；叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。；真核细胞获得高效产能和光合作用能力。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s72_exam","q":"关于本页「（四）真核细胞是从原核细胞进化而来的」，下列哪项表述正确？","o":["A. 例1 NaOH 与浓盐酸稀释","B. 第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。","C. B：C—C 单键可绕键轴自由旋转，产生不同构象。","D. 内共生学说：线粒体源于被吞入的需氧细菌。"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「例题：溶液配制、pH 与缓冲液」的内容，不是本页核心。","属于「（一）现代生物化学的发展和分子生物学的兴起」的内容，不是本页核心。","属于「图1-2 碳成键的几何学」的内容，不是本页核心。","本页要点：内共生学说：线粒体源于被吞入的需氧细菌。"],"src":"期末·选择题"},"source":"老师第1章PPT 第72页","imageExplain":"这张图在讲：内共生学说是重点：线粒体/叶绿体有自身环状DNA、70S核糖体、双层膜，支持其细菌起源。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：内共生学说：线粒体源于被吞入的需氧细菌。；叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。。","srcType":"原书","role":"查阅"},{"i":72,"sec":"第1章 原书版课件","title":"图1-20 地球上生命进化的里程碑","notes":"图1-20是竖轴时间线，数值从下往上变小。读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆。","img":"assets/img/bc01deck/slide-73.jpg?v=20261108eg","points":["图1-20是竖轴时间线，数值从下往上变小","读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆"],"check":{"kind":"short","id":"bc01_s73_check","q":"按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。","a":"参考要点：图1-20是竖轴时间线，数值从下往上变小；读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆","e":"解析：图1-20是竖轴时间线，数值从下往上变小。读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆。 关键点：图1-20是竖轴时间线，数值从下往上变小；读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆","src":"本页自测"},"imageExplain":"本页为原书配图：图1-20 地球上生命进化的里程碑。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。","exam":{"kind":"mcq","id":"bc01_s73_exam","q":"关于本页「图1-20 地球上生命进化的里程碑」，下列哪项表述正确？","o":["A. 图1-20是竖轴时间线，数值从下往上变小","B. DNA是主要遗传物质：信息量大、稳定、可忠实复制。","C. 微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。","D. 蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。"],"a":"A","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["本页要点：图1-20是竖轴时间线，数值从下往上变小","属于「（三）自我复制和自我装配是生命状态的精华」的内容，不是本页核心。","属于「（一）生命元素」的内容，不是本页核心。","属于「（四）生物大分子及其单体亚基」的内容，不是本页核心。"],"src":"期末·选择题"},"source":"老师第1章PPT 第73页","srcType":"原书","role":"查阅"},{"i":73,"sec":"第1章 原书版课件","title":"第8节 · 3句话 + 2题自测","notes":"第8节收束：化学进化→RNA世界→原始细胞→内共生。","img":"","points":["化学进化：无机小分子→有机小分子→生物大分子。","RNA 世界：RNA 既能贮信息又能催化；后来 DNA 贮存、蛋白质催化。","原始细胞出现后进入生物进化；内共生学说解释线粒体/叶绿体起源。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_wrap8_1","kind":"mcq","q":"RNA世界假说的核心是？","o":["A. RNA只贮存信息","B. RNA既贮存信息又能催化","C. DNA能催化","D. 蛋白质贮存信息"],"a":"B","e":"RNA同时具有信息与催化功能，解决“先DNA还是先蛋白质”的循环。","oe":["RNA也能催化。","正确。","DNA主要贮存信息。","蛋白质主要执行功能。"],"src":"本节收束"},{"id":"bc01_wrap8_2","kind":"mcq","q":"内共生学说的证据不包括？","o":["A. 线粒体有自身DNA","B. 线粒体有70S核糖体","C. 线粒体有双层膜","D. 线粒体有80S核糖体"],"a":"D","e":"线粒体有自身DNA、70S核糖体和双层膜；80S是真核胞质核糖体。","oe":["是证据。","是证据。","是证据。","线粒体不是80S。"],"src":"本节收束"}],"quizTitle":"本节收束：2题自测","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":74,"sec":"第1章 原书版课件","title":"第8节难点：RNA世界与内共生","notes":"第8节难点：RNA世界用“信息+催化”一条逻辑；内共生用四条证据。","img":"","points":["RNA既贮信息又催化→解决“先DNA还是先蛋白质”的循环。","DNA接管贮存，蛋白质接管催化，原始细胞出现。","线粒体/叶绿体有自身DNA、70S核糖体、双层膜、分裂方式。"],"check":null,"imageExplain":"","quiz":[{"id":"bc01_break75","kind":"short","q":"说明RNA世界逻辑，并列出内共生学说的证据。","a":"得分点：RNA信息+催化→DNA贮存/蛋白质催化→原始细胞；线粒体/叶绿体有自身DNA、70S核糖体、双层膜。","kps":"按得分点分条回答","src":"难点拆解"}],"quizTitle":"难点拆解：网页练习","source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":75,"sec":"第1章 原书版课件","title":"第1章 · 三条主线与高频考点","notes":"用三条主线收束全章：生命属性、生物分子（结构/构象/非共价作用）、水与细胞及起源。让学生先能复述框架，再补细节。","img":"assets/img/bc01deck/slide-76.jpg?v=20261108eg","points":["化学成分复杂而同一","小分子/大分子/单体","水的性质与pH/缓冲","化学进化与RNA世界"],"check":{"kind":"short","id":"bc01_s76_check","q":"本页「第1章 · 三条主线与高频考点」的核心要点是什么？请写出至少3点，并解释其中一点。","a":"参考要点：化学成分复杂而同一；小分子/大分子/单体；水的性质与pH/缓冲；化学进化与RNA世界","e":"解析：用三条主线收束全章：生命属性、生物分子（结构/构象/非共价作用）、水与细胞及起源。让学生先能复述框架，再补细节。 关键点：化学成分复杂而同一；小分子/大分子/单体；水的性质与pH/缓冲","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s76_exam","q":"关于本页「第1章 · 三条主线与高频考点」，下列哪项表述正确？","o":["A. 重点认羟基、羰基、羧基、酯基、磷酸基。","B. D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。","C. 水平键朝前、垂直键朝后；与甘油醛比较定D/L。","D. 化学成分复杂而同一"],"a":"D","e":"正确项来自本页；其余选项属于其他页/其他知识点，不能作为本页的核心表述。","oe":["属于「图1-3 局部放大（上）：含氧官能团」的内容，不是本页核心。","属于「（三）构型的命名系统」的内容，不是本页核心。","属于「第4节难点：构型、构象与D/L」的内容，不是本页核心。","本页要点：化学成分复杂而同一"],"src":"期末·选择题"},"source":"老师第1章PPT 第76页","imageExplain":"这张图在讲：用三条主线收束全章：生命属性、生物分子（结构/构象/非共价作用）、水与细胞及起源。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：化学成分复杂而同一；小分子/大分子/单体。","srcType":"原书","role":"查阅"},{"i":76,"sec":"第1章 原书版课件","title":"课堂自测：5道题（网页互动）","notes":"本页为互动课堂自测：4道选择题 + 1道填空题。选完后立即显示正确答案、解析和选项解析；答错自动进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quiz":[{"id":"bc01_quiz1","kind":"mcq","q":"下列元素中，属于生物体微量元素的是？","o":["A. 碳","B. 氢","C. 氧","D. 铁"],"a":"D","e":"Fe 属于微量元素；C、H、O 是大量元素。","oe":["碳是大量元素。","氢是大量元素。","氧是大量元素。","铁含量低但是必需微量元素。"],"src":"课堂自测"},{"id":"bc01_quiz2","kind":"mcq","q":"蛋白质的α螺旋变为β折叠，属于哪种变化？","o":["A. 结构异构","B. 构型改变","C. 构象改变","D. 共价键断裂"],"a":"C","e":"α螺旋、β折叠都是二级结构，通过单键旋转互变，属于构象改变。","oe":["结构异构是原子连接次序不同。","构型改变需要断裂共价键。","构象改变只需单键旋转。","没有共价键断裂。"],"src":"课堂自测"},{"id":"bc01_quiz3","kind":"mcq","q":"生物大分子通常指相对分子质量大于多少的多聚体？","o":["A. 500","B. 1000","C. 5000","D. 50000"],"a":"C","e":"教材以5000作为生物大分子的常用界限。","oe":["500太小。","1000仍偏小。","5000是常用界限。","50000不是通用界限。"],"src":"课堂自测"},{"id":"bc01_quiz4","kind":"mcq","q":"水具有高热容，主要原因是？","o":["A. 水分子很小","B. 水分子间大量氢键","C. 水不含碳","D. 水是中性分子"],"a":"B","e":"水分子间大量氢键吸收热量，使水具有高热容。","oe":["分子小不是主要原因。","氢键网络吸收热量。","是否含碳与热容无关。","中性不是原因。"],"src":"课堂自测"},{"id":"bc01_quiz5","kind":"fill","q":"蛋白质在等电点（pI）时，净电荷为______。","a":"零","e":"等电点时蛋白质净电荷为零；也可写0。","src":"课堂自测"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":77,"sec":"第1章 原书版课件","title":"课堂自测：错题本与复习清单","notes":"完成上一页5道题后，用错题本复盘；再按“错题→本页短答→课后题→章末测试”的顺序复习。","img":"","points":[],"check":null,"imageExplain":"","quizReview":true,"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":78,"sec":"第1章 原书版课件","title":"计算专项（一）：溶液配制与稀释","notes":"n=cV：n 是物质的量(mol)，c 是浓度(mol/L)，V 是体积(L)；m=nM 中 M 是摩尔质量(g/mol)。c=1000ρw/M 中 ρ 是密度(g/mL)、w 是质量分数。","img":"","points":["n=cV；m=nM；质量浓度=m/V","c=1000ρw/M；稀释前后n不变","NaOH 渗透压浓度要乘粒子数 i=2"],"check":null,"imageExplain":"","quizTitle":"计算题专项（网页互动）","quiz":[{"id":"bc01_calc1","kind":"fill","q":"配制 0.4 mol/L NaOH 溶液 500 mL，需要 NaOH 多少 g？","a":"8","e":"n=0.4×0.500=0.20 mol；m=0.20×40=8.0 g。","src":"计算专项"},{"id":"bc01_calc2","kind":"fill","q":"用 37%、1.20 g/mL 浓盐酸配制 0.5 mol/L HCl 2000 mL，需浓盐酸多少 mL？","a":"82.2","e":"c=1000×1.20×0.37÷36.5≈12.16 mol/L；n=0.5×2=1.00 mol；V=1.00÷12.16≈0.0822 L=82.2 mL。","src":"计算专项"}],"symbols":[{"sym":"n","mean":"物质的量","unit":"mol"},{"sym":"c","mean":"物质的量浓度","unit":"mol/L"},{"sym":"V","mean":"溶液体积","unit":"L（500 mL=0.500 L）"},{"sym":"m","mean":"溶质质量","unit":"g"},{"sym":"M","mean":"摩尔质量","unit":"g/mol（NaOH=40）"},{"sym":"ρ","mean":"密度","unit":"g/mL"},{"sym":"w","mean":"质量分数","unit":"小数或百分数（37%=0.37）"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":79,"sec":"第1章 原书版课件","title":"计算专项（二）：pH、Ka 与缓冲液","notes":"pH=−lg[H⁺]：先由pH换算出[H⁺]；Ka=[H⁺][A⁻]/[HA]，弱酸近似 Ka≈[H⁺]²/(c−[H⁺])；pKa=−lgKa。Henderson-Hasselbalch：pH=pKa+lg([A⁻]/[HA])。","img":"","points":["pH=−lg[H⁺]","Ka≈[H⁺]²/(c−[H⁺])；pKa=−lgKa","pH=pKa+lg([盐]/[酸])"],"check":null,"imageExplain":"","quizTitle":"计算题专项（网页互动）","quiz":[{"id":"bc01_calc3","kind":"fill","q":"0.02 mol/L 弱酸溶液 pH=4.6，其 pKa 约为多少？","a":"7.5","e":"[H⁺]=10⁻⁴·⁶≈2.51×10⁻⁵ mol/L；Ka≈(2.51×10⁻⁵)²/0.02≈3.15×10⁻⁸；pKa≈7.50。","src":"计算专项"},{"id":"bc01_calc4","kind":"fill","q":"0.20 mol/L NaAc + 0.60 mol/L HAc（pKa=4.76）的 pH 是多少？","a":"4.28","e":"pH=4.76+lg(0.20/0.60)=4.76−0.477≈4.28。","src":"计算专项"}],"symbols":[{"sym":"[H⁺]","mean":"氢离子浓度","unit":"mol/L"},{"sym":"pH","mean":"−lg[H⁺]","unit":"无量纲"},{"sym":"Ka","mean":"酸解离常数","unit":"常用 mol/L 表示；越大酸性越强"},{"sym":"pKa","mean":"−lgKa","unit":"无量纲；pH=pKa时[A⁻]=[HA]"},{"sym":"HA","mean":"弱酸分子","unit":"未解离形式"},{"sym":"A⁻","mean":"共轭碱","unit":"解离后形式"},{"sym":"c","mean":"弱酸总浓度","unit":"mol/L；c=[HA]+[A⁻]"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":80,"sec":"第1章 原书版课件","title":"计算专项（三）：缓冲液配比","notes":"缓冲液计算：r=10^(pH−pKa)=[A⁻]/[HA]，再用总浓度 C=[A⁻]+[HA] 解方程组；[A⁻]是盐浓度，[HA]是酸浓度。","img":"","points":["r=10^(pH−pKa)=[盐]/[酸]","x+y=C（总浓度）","pH=pKa±1 缓冲能力较强"],"check":null,"imageExplain":"","quizTitle":"计算题专项（网页互动）","quiz":[{"id":"bc01_calc5","kind":"fill","q":"0.2 mol/L、pH=5.0 醋酸缓冲液（pKa=4.76），醋酸钠浓度约为多少 mol/L？","a":"0.127","e":"x/y=10^(5.0−4.76)=1.74；x+y=0.2；x≈0.127 mol/L，y≈0.073 mol/L。","src":"计算专项"},{"id":"bc01_calc6","kind":"fill","q":"上题中醋酸的浓度约为多少 mol/L？","a":"0.073","e":"x+y=0.2，x/y≈1.74；解得 x≈0.127，y≈0.073 mol/L。","src":"计算专项"}],"symbols":[{"sym":"[A⁻]","mean":"共轭碱/盐浓度","unit":"mol/L（如 NaAc）"},{"sym":"[HA]","mean":"弱酸浓度","unit":"mol/L（如 HAc）"},{"sym":"r","mean":"[A⁻]/[HA]","unit":"盐/酸浓度比，无量纲"},{"sym":"C","mean":"缓冲液总浓度","unit":"mol/L；C=[A⁻]+[HA]"},{"sym":"pKa","mean":"酸解离常数的负对数","unit":"无量纲"},{"sym":"pH","mean":"pKa+lg([A⁻]/[HA])","unit":"无量纲"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":81,"sec":"原书课后题","title":"附录C：原书课后题（网页互动）","notes":"本附录把15道原书课后题做成网页互动题：先独立作答，再展开参考答案；答错/不会可进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizIntro":["Q1—Q2：学科定义、生命元素与碳/硅比较","Q3—Q4：手性选择、消旋体与对映体活性","Q5—Q6：四类非共价作用、水的高热容","Q7—Q13：溶液配制、稀释、pH/Ka、共轭酸碱、缓冲液","Q14—Q15：大肠杆菌计算、表面-体积比"],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":82,"sec":"原书课后题","title":"第1题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac1","modI":0,"q":"生物化学研究什么？它作为一门学科是怎样发展起来的？它与分子生物学有什么关系？","a":"(1) 生物化学研究生命属性的化学本质，包括生物分子的结构与功能、物质代谢与调节、遗传信息传递与表达等。\n(2) 现代生物化学大体经历三个阶段：静态/叙述生物化学（1770—1900，研究组成、分离、结构）→ 动态生物化学（1900—1950，研究代谢、酶、能量）→ 分子生物化学（1950年以后，研究大分子结构与分子机制）。\n(3) 分子生物学是生物化学发展的新阶段，研究DNA、RNA、蛋白质等生物大分子及其相互关系。","kps":"研究内容1分；三阶段各1分；与分子生物学关系1分","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"先答定义，再按“静态—动态—分子”三阶段，最后说二者关系；不要只写年份。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":83,"sec":"原书课后题","title":"第2题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac2","modI":0,"q":"进化过程中生命元素是怎样被选择的？硅和碳同为IVA族、都能形成4个单键，为什么硅没有成为生命骨架？","a":"(1) 生命元素的选择与环境中原料的可得性有关，也取决于元素及其化合物对生命过程特殊作用的适合性。\n(2) 碳能形成稳定的C—C单键、双键和三键，可构成链状、分支和环状骨架；CO₂溶于水，有利于碳循环。\n(3) 硅原子较大，Si—Si键比C—C弱，Si的多聚物遇水不稳定，SiO₂难溶于水，不利于在需氧环境中循环，因此硅只以痕量存在。","kps":"元素选择两个原因；C与Si比较：成键、稳定性、溶解性、循环","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"答“选择原因+碳的优势+硅的局限”三点；不要只说“碳是生命元素”。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":84,"sec":"原书课后题","title":"第3—4题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac3","modI":0,"q":"原始生物分子有立体异构体时，为什么生物几乎只利用一种异构体（如L-氨基酸、D-单糖）？","a":"现有观点认为：酶对底物具有立体专一性。生命起源后，具有选择性的酶和蛋白质逐步进化；代谢反应几乎都由酶催化，酶只与特定构型的底物结合，因此生物体优先利用一种对映体。","kps":"关键：酶对底物的立体专一性；不是化学合成偏倚","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"关键词是“酶促反应的立体专一性”，不是“另一种不存在”。","kind":"short"},{"id":"bc01_ac4","modI":0,"q":"苯丙胺（benzedrine）是消旋体，右旋苯丙胺（dexedrine）是单一活性对映体。为什么达到同样效应，消旋体所需剂量约为右旋体的2倍？","a":"该药物含一个手性碳，有一对对映体。右旋体（dexedrine）是主要活性形式；消旋体（benzedrine）中只有一半是右旋体，另一半左旋体活性很低，因此要达到同样生理效应，消旋体剂量约为右旋体的2倍。","kps":"手性碳；对映体；消旋体只有一半活性；剂量差2倍","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"核心：消旋体=等量对映体，只有一种有高活性。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":85,"sec":"原书课后题","title":"第5—6题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac5","modI":0,"q":"生物分子间和分子内的非共价相互作用有哪些？它们有什么区别？","a":"主要包括离子相互作用、氢键、范德华力和疏水作用。\n(1) 离子相互作用：带电基团间的静电吸引，受盐浓度和介电常数影响。\n(2) 氢键：H与N/O/F孤对电子作用，有方向性和饱和性。\n(3) 范德华力：瞬时偶极诱导，作用距离短，要求紧密堆积。\n(4) 疏水作用：非极性基团避水聚集，本质是水氢键网络的熵驱动。","kps":"四类非共价作用；每类特点：键能、方向性、饱和性、距离依赖","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"四类作用按“本质—特点—例子”比较；疏水作用不是一种吸引键。","kind":"short"},{"id":"bc01_ac6","modI":0,"q":"解释为什么水分子之间形成氢键会造成高比热容。","a":"水分子间形成大量氢键，构成动态氢键网络。加热时，一部分能量用于断裂氢键，而不是全部用于增加分子动能，因此使水温升高需要较多热量，表现为高比热容。氢键还具有协同性，使水的内聚力较大。","kps":"水的极性/氢键；氢键网络；吸热用于断氢键","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"关键词：氢键网络、断氢键耗能、温度升高慢。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":86,"sec":"原书课后题","title":"第7—8题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac7","modI":0,"q":"【计算】配制 0.4 mol/L NaOH 溶液 500 mL：(1) 需要多少克固体 NaOH？(2) 用质量浓度（g/L）和摩尔渗透压浓度表示该溶液。","a":"(1) n=cV=0.4 mol/L×0.500 L=0.20 mol；m=nM=0.20 mol×40 g/mol=8.0 g。\n(2) 质量浓度=8.0 g÷0.500 L=16 g/L；NaOH 完全解离为 Na⁺ 和 OH⁻，粒子总浓度=2×0.4=0.8 mol/L，故摩尔渗透压浓度=0.8 mol/L（即 0.8 osmol/L）。","kps":"n=cV；m=nM；质量浓度=m/V；渗透压浓度=粒子数×摩尔浓度","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"先算物质的量，再算质量；质量浓度用“溶质质量÷溶液体积”；渗透压浓度要乘粒子数。注意 500 mL=0.500 L。","kind":"short"},{"id":"bc01_ac8","modI":0,"q":"【计算】配制 0.5 mol/L 盐酸 2000 mL，需要量取浓盐酸（质量分数 37%，密度 1.20 g/mL）多少 mL？","a":"浓盐酸的物质的量浓度：c=1000ρw/M=1000×1.20×0.37÷36.5≈12.16 mol/L。\n所需 HCl：n=cV=0.5 mol/L×2.00 L=1.00 mol。\n所需浓盐酸体积：V=n/c=1.00 mol÷12.16 mol/L≈0.0822 L=82.2 mL。","kps":"c=1000ρw/M；稀释前后n不变；V=n/c","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"先把质量分数换算成物质的量浓度，再用稀释前后 HCl 物质的量不变。易错：把 2000 mL 当成 2000 L，或直接用 37% 当浓度。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":87,"sec":"原书课后题","title":"第9—10题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac9","modI":0,"q":"【计算】某弱酸溶液浓度为 0.02 mol/L，测得 pH=4.6：(1) 求[H⁺]；(2) 求该酸的 Ka 和 pKa。","a":"(1) pH=4.6，[H⁺]=10⁻⁴·⁶≈2.51×10⁻⁵ mol/L。\n(2) 弱酸 HA 解离：Ka≈[H⁺]²/(c−[H⁺])。\nKa≈(2.51×10⁻⁵)²/(0.02−2.51×10⁻⁵)≈3.15×10⁻⁸。\npKa=−lgKa≈7.50。","kps":"pH→[H+]；弱酸Ka≈[H+]^2/(c−[H+])；pKa=−lgKa","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"pH 是负对数，先换成浓度；弱酸解离用 Ka=[H⁺][A⁻]/[HA]，当[H⁺]远小于 c 时可近似 c−[H⁺]≈c。","kind":"short"},{"id":"bc01_ac10","modI":0,"q":"判断共轭酸碱对：H₂PO₄⁻/HPO₄²⁻、HCO₃⁻/CO₃²⁻、HCOOH/HCOO⁻中，哪个是共轭酸？","a":"共轭酸是给出质子后变成对应碱的物种，即每对中多一个H⁺的成员：\n(1) H₂PO₄⁻；(2) HCO₃⁻；(3) HCOOH。\n它们分别给出H⁺后形成HPO₄²⁻、CO₃²⁻、HCOO⁻。","kps":"共轭酸=得到质子后的形式；逐对判断","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"先找“多一个H⁺”的物种；共轭酸/共轭碱只差一个质子。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":88,"sec":"原书课后题","title":"第11—12题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac11","modI":0,"q":"【计算】溶液含 0.20 mol/L 醋酸钠和 0.60 mol/L 醋酸（pKa=4.76），求 pH。","a":"用 Henderson-Hasselbalch 方程：pH=pKa+lg([NaAc]/[HAc])。\npH=4.76+lg(0.20/0.60)=4.76+lg(1/3)=4.76−0.477≈4.28。","kps":"Henderson-Hasselbalch：pH=pKa+lg([A−]/[HA])","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"盐浓度在分子、酸浓度在分母；比值小于 1 时 pH 低于 pKa。不要代反。","kind":"short"},{"id":"bc01_ac12","modI":0,"q":"【计算】配制 0.2 mol/L、pH=5.0 的醋酸盐缓冲液，求所需醋酸和醋酸钠的浓度（醋酸 pKa=4.76）。","a":"设[NaAc]=x，[HAc]=y，则 x+y=0.2 mol/L。\n由 pH=pKa+lg(x/y)：5.0=4.76+lg(x/y)，lg(x/y)=0.24，x/y≈1.74。\n联立解得 x≈0.127 mol/L，y≈0.073 mol/L。\n即醋酸钠约 0.127 mol/L，醋酸约 0.073 mol/L。","kps":"pH=pKa+lg([盐]/[酸])；x+y=总浓度；解对数方程","freq":"常考","prio":"A","req":"理解","src":"原书课后题","e":"先由 pH 与 pKa 求盐/酸比值，再用总浓度守恒解方程组。易错：把 x/y 写成 y/x，或忘记 x+y=0.2。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":89,"sec":"原书课后题","title":"第13题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac13","modI":0,"q":"计算醋酸钠和醋酸（pKa=4.76）的物质的量比为 (1) 2:1 和 (2) 1:10 的稀溶液的 pH。","a":"(1) pH=pKa+lg([NaAc]/[HAc])=4.76+lg2=4.76+0.30=5.06。\n(2) pH=4.76+lg(1/10)=4.76−1.00=3.76。","kps":"pH=pKa+lg(盐/酸)；2:1→lg2；1:10→lg(1/10)","freq":"原书课后题","prio":"A","req":"掌握","src":"原书课后题","e":"盐/酸比例大于1时pH>pKa；比例小于1时pH<pKa。先取对数再加减。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":90,"sec":"原书课后题","title":"第14题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac14","modI":0,"q":"大肠杆菌短杆状，长约2 μm、直径0.8 μm（按圆柱体，V=πr²h）：(1) 首尾相连横跨直径0.5 mm针头需多少个？(2) 平均密度1.1×10³ g/L，一个细胞质量多少？(3) 被膜厚10 nm，占总体积百分之几？(4) 约15000个核糖体（直径18 nm），占细胞体积百分之几？(5) 葡萄糖约1 mmol/L，一个细胞含多少个葡萄糖分子？","a":"(1) 0.5 mm=500 μm；500÷2=250个。\n(2) V=πr²h=3.14×(0.4 μm)²×2 μm≈1.0048 μm³；m=ρV=1.1×10³ g/L×1.0048×10⁻¹⁵ L≈1×10⁻¹² g=1 pg。\n(3) 表面积=2πrh+2πr²≈6.0288 μm²；被膜体积≈6.0288×10×10⁻³ μm³≈0.06 μm³；占比≈6%。\n(4) 15000个核糖体体积≈0.0458 μm³；占比≈5%。\n(5) 1.0048 μm³=1.0048×10⁻¹⁵ L；n=1.0048×10⁻¹⁵×1×10⁻³=1.0048×10⁻¹⁸ mol；分子数≈6.04×10⁵个。","kps":"圆柱体V=πr²h；m=ρV；表面积；体积分数；n=cV；N=nNA","freq":"原书课后题","prio":"A","req":"理解","src":"原书课后题","e":"单位统一是难点：μm→dm/L、nm→μm。先算体积，再算质量/表面积/分子数；百分数用“部分/总体积”。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":91,"sec":"原书课后题","title":"第15题","notes":"原书课后题：先写答案要点/步骤，再展开参考答案核对；可标记“我不会”进入错题本。","img":"","points":[],"check":null,"imageExplain":"","quizTitle":"原书课后题（网页互动）","quiz":[{"id":"bc01_ac15","modI":0,"q":"高速率细菌代谢要求高的表面-体积比：(1) 为什么表面-体积比影响代谢最高速率？(2) 计算淋病奈瑟球菌（直径0.5 μm）与球状阿米巴（直径150 μm）的表面-体积比，并比较。","a":"(1) 代谢速率受扩散限制，而扩散与表面积有关；表面-体积比越大，单位体积可交换的表面积越大，物质交换越快。\n(2) 球体 S/V=4πr²/(4/3πr³)=3/r。\n球菌：3/0.25 μm=12 μm⁻¹；阿米巴：3/75 μm=0.04 μm⁻¹。\n球菌的S/V约为阿米巴的12÷0.04=300倍。","kps":"球体S/V=3/r；r越小S/V越大；扩散限制","freq":"原书课后题","prio":"A","req":"理解","src":"原书课后题","e":"直接用S/V=3/r，注意半径不是直径；比较倍数=12/0.04=300。","kind":"short"}],"source":"AI整理（依据老师PPT/原书）","srcType":"原书","role":"查阅"},{"i":92,"sec":"反应式四步卡","title":"图1-14 醋酸滴定/缓冲：pH怎么变？","notes":"图1-14四步卡：弱酸滴定、原子记账、缓冲、体内外。","img":"assets/img/bc01deck/slide-93.jpg?v=20261108eg","points":["弱酸HA+强碱NaOH；25℃。","OH⁻夺H⁺，生成A⁻和H₂O。","pH=pKa时半解离；pKa±1缓冲。","体外滴定 vs 体内缓冲。"],"check":{"kind":"short","id":"bc01_s93_check","q":"本页滴定反应的条件、原子记账、键数/曲线、体内外对比是什么？","a":"参考要点：弱酸HA+强碱NaOH；25℃。；OH⁻夺H⁺，生成A⁻和H₂O。；pH=pKa时半解离；pKa±1缓冲。；体外滴定 vs 体内缓冲。","e":"解析：图1-14四步卡：弱酸滴定、原子记账、缓冲、体内外。 关键点：弱酸HA+强碱NaOH；25℃。；OH⁻夺H⁺，生成A⁻和H₂O。；pH=pKa时半解离；pKa±1缓冲。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s93_exam","q":"关于醋酸滴定，下列哪项正确？","o":["A. pH=pKa时[A⁻]=[HA]","B. 滴定与质子转移无关","C. pKa±1无缓冲能力","D. 体内pH只由水决定"],"a":"A","e":"pH=pKa时半解离，缓冲最强。","oe":["正确。","错误。","错误。","错误。"],"src":"期末·选择题"},"source":"老师第1章PPT 第93页","imageExplain":"这张图在讲：图1-14四步卡：弱酸滴定、原子记账、缓冲、体内外。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：弱酸HA+强碱NaOH；25℃。；OH⁻夺H⁺，生成A⁻和H₂O。。","srcType":"老师PPT/教材","role":"查阅"},{"title":"卡点闭环1-诊断页：pH与缓冲","notes":"先做：弱酸HA的pKa=5.0，缓冲液pH=5.0时，[A⁻]/[HA]最接近？","points":["A. 0","B. 1","C. 10","D. 100"],"table":[["常见错答","错在哪"],["选A","pH=pKa不是全质子化"],["选C","把pH差1当成10倍（方向也反）"],["选D","把差2当100倍"]],"tableTitle":"答案：B。pH=pKa时[A⁻]=[HA]，比值为1。","sec":"第01章 · 卡点闭环","i":93,"srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-例题：缓冲液配比","notes":"Henderson-Hasselbalch：pH=pKa+log([A⁻]/[HA])。乙酸pKa=4.76，目标pH=5.00：log比值=0.24，比值≈1.74。若总浓度0.10 M，则[HA]≈0.0365 M，[A⁻]≈0.0635 M。","points":["第1步：写H-H方程。","第2步：pH−pKa=log比值。","第3步：10的幂求比值。","第4步：按总浓度分配。"],"check":{"kind":"short","id":"bc01_c1_ex","q":"pKa=5，pH=6，[A⁻]/[HA]约为？","a":"10^1=10。","e":"解析：Henderson-Hasselbalch：pH=pKa+log([A⁻]/[HA])。乙酸pKa=4.76，目标pH=5.00：log比值=0.24，比值≈1.74。若总浓度0.10 M，则[HA]≈0.0365 M，[A⁻]≈0.0635 M。 关键点：第1步：写H-H方程。；第2步：pH−pKa=log比值。；第3步：10的幂求比值。","src":"卡点闭环·例题"},"sec":"第01章 · 卡点闭环","i":94,"srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-变式：比值三连","notes":"先算pH−pKa，再取10的幂；比值>1说明去质子化形式多。","table":[["pH−pKa","[A⁻]/[HA]","主要形式"],["−1","0.1","HA"],["0","1","各半"],["+0.24","1.74","A⁻略多"],["+2","100","A⁻"]],"tableTitle":"变式答案：每高1个pH单位，比值×10。","sec":"第01章 · 卡点闭环","i":95,"srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-错因：缓冲三个误读","notes":"错因：①pH=pKa时以为全为HA；②把“高1个pH单位”记成2倍；③缓冲容量与浓度无关。","points":["pH=pKa→[A⁻]=[HA]。","pH高1→比值10:1。","缓冲容量随总浓度增大。","最有效缓冲范围pKa±1。","算完用总浓度检查。"],"sec":"第01章 · 卡点闭环","i":96,"srcType":"白话辅助","role":"练习"},{"i":97,"sec":"反应式四步卡","title":"水、弱酸弱碱电离与缓冲：H⁺去哪了？","notes":"水/弱酸弱碱：H⁺转移；Kw、Ka、pH、缓冲对；体内外对比。","img":"assets/img/bc01deck/slide-94.jpg?v=20261108eg","points":["水/弱酸弱碱；25℃稀溶液。","H₂O/HA给出H⁺，A⁻/OH⁻接受H⁺。","Kw/Ka/pH；缓冲对A⁻/HA。","体内缓冲 vs 体外滴定。"],"check":{"kind":"short","id":"bc01_s94_check","q":"本页水/弱酸弱碱反应的条件、原子记账、平衡/键、体内外对比是什么？","a":"参考要点：水/弱酸弱碱；25℃稀溶液。；H₂O/HA给出H⁺，A⁻/OH⁻接受H⁺。；Kw/Ka/pH；缓冲对A⁻/HA。；体内缓冲 vs 体外滴定。","e":"解析：水/弱酸弱碱：H⁺转移；Kw、Ka、pH、缓冲对；体内外对比。 关键点：水/弱酸弱碱；25℃稀溶液。；H₂O/HA给出H⁺，A⁻/OH⁻接受H⁺。；Kw/Ka/pH；缓冲对A⁻/HA。","src":"本页自测"},"exam":{"kind":"mcq","id":"bc01_s94_exam","q":"关于水/弱酸弱碱电离，下列哪项正确？","o":["A. HA给出H⁺，A⁻接受H⁺","B. pH越高[H⁺]越大","C. pKa与缓冲无关","D. 体内不需要缓冲"],"a":"A","e":"共轭酸碱对；pH=−lg[H⁺]。","oe":["正确。","错误。","错误。","错误。"],"src":"期末·选择题"},"source":"老师第1章PPT 第94页","imageExplain":"这张图在讲：水/弱酸弱碱：H⁺转移。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：水/弱酸弱碱；25℃稀溶液。；H₂O/HA给出H⁺，A⁻/OH⁻接受H⁺。。","srcType":"老师PPT/教材","role":"查阅"}]}],"mcq":[{"id":"bc01_exam_mcq1","modI":0,"q":"下列元素中，属于生物体微量元素的是？","o":["A. 碳","B. 氢","C. 铁","D. 氧"],"a":"C","e":"Fe属于微量元素；C、H、O是大量元素。","oe":["碳是大量元素。","氢是大量元素。","铁在生物体中含量很低，是微量元素。","氧是大量元素。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_14"},{"id":"bc01_exam_mcq2","modI":0,"q":"生物大分子通常指相对分子质量大于多少的多聚体？","o":["A. 500","B. 1000","C. 5000","D. 50000"],"a":"C","e":"教材中生物大分子一般指相对分子质量大于5000的多聚体，如蛋白质、核酸、多糖。","oe":["500太小。","1000仍偏小。","5000是常用界限。","50000不是通用界限。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_14"},{"id":"bc01_exam_mcq3","modI":0,"q":"蛋白质、核酸和多糖的单体依次是？","o":["A. 氨基酸、核苷酸、单糖","B. 单糖、氨基酸、核苷酸","C. 核苷酸、单糖、氨基酸","D. 脂肪酸、氨基酸、核苷酸"],"a":"A","e":"蛋白质由氨基酸组成，核酸由核苷酸组成，多糖由单糖组成。","oe":["顺序正确。","单糖是多糖单体，不是蛋白质单体。","核苷酸是核酸单体。","脂肪酸不是蛋白质的单体。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_14"},{"id":"bc01_exam_mcq4","modI":0,"q":"蛋白质的α螺旋变为β折叠，属于哪种变化？","o":["A. 结构异构","B. 构型改变","C. 构象改变","D. 共价键断裂"],"a":"C","e":"α螺旋和β折叠都是二级结构，通过单键旋转互变，不涉及共价键断裂，属于构象改变。","oe":["结构异构是原子连接次序不同。","构型改变需要断裂共价键。","构象改变只需单键旋转，α螺旋/β折叠属于此类。","没有共价键断裂。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_26"},{"id":"bc01_exam_mcq5","modI":0,"q":"一对对映体之间的关系是？","o":["A. 互为镜像且能重合","B. 互为镜像但不能重合","C. 结构完全相同","D. 连接次序不同"],"a":"B","e":"对映体互为镜像但不能重合，物理性质基本相同，旋光方向相反，生物活性可不同。","oe":["镜像分子不能重合。","正确：镜像、不能重合。","不是完全相同。","连接次序相同，空间构型不同。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_26"},{"id":"bc01_exam_mcq6","modI":0,"q":"蛋白质折叠中，把非极性侧链聚集到内部的主要作用力是？","o":["A. 离子键","B. 氢键","C. 疏水作用","D. 二硫键"],"a":"C","e":"非极性侧链避水聚集，主要由疏水作用（熵驱动）推动，是蛋白质折叠的重要驱动力。","oe":["离子键发生在带电基团间。","氢键主要稳定二级结构。","疏水作用把非极性基团聚集到内部。","二硫键是共价交联，不是主要折叠驱动力。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_38"},{"id":"bc01_exam_mcq7","modI":0,"q":"水具有高热容，主要原因是？","o":["A. 水分子很小","B. 水分子间形成大量氢键","C. 水不含碳","D. 水是中性分子"],"a":"B","e":"水分子间形成大量氢键，加热时部分能量用于断氢键，因此温度升高所需热量大。","oe":["分子小不是主要原因。","氢键网络吸收热量，导致高热容。","是否含碳与热容无关。","中性不是高热容的原因。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_38"},{"id":"bc01_exam_mcq8","modI":0,"q":"缓冲液中[A−]=[HA]时，pH等于？","o":["A. pKa","B. 7.0","C. pI","D. 0"],"a":"A","e":"Henderson-Hasselbalch方程pH=pKa+lg([A−]/[HA])；当[A−]=[HA]时，lg1=0，pH=pKa。","oe":["正确：pH=pKa。","pH7只在中性缓冲时接近。","pI是等电点，不是缓冲对pKa。","pH0是强酸性。"],"kp":"","freq":"期末风格","prio":"A","req":"掌握","kpId":"bc01_s0_53"}],"judge":[{"id":"bc01_exam_judge1","modI":0,"q":"微量元素在生物体中含量很低，但仍是生命活动必需的。","a":"对","e":"Fe、Zn、Cu、Mn等微量元素含量低，但参与酶、辅酶等，必需。","kp":"","kpId":"bc01_s0_14"},{"id":"bc01_exam_judge2","modI":0,"q":"对映体的物理性质完全相同，生物活性也完全相同。","a":"错","e":"对映体物理性质基本相同，但生物活性常不同，酶和受体具有手性识别。","kp":"","kpId":"bc01_s0_26"},{"id":"bc01_exam_judge3","modI":0,"q":"构象改变需要断裂共价键。","a":"错","e":"构象改变只需单键旋转；构型改变才涉及共价键断裂。","kp":"","kpId":"bc01_s0_26"},{"id":"bc01_exam_judge4","modI":0,"q":"水的高热容与分子间氢键有关。","a":"对","e":"水分子间大量氢键吸收热量，使水具有高热容。","kp":"","kpId":"bc01_s0_38"},{"id":"bc01_exam_judge5","modI":0,"q":"原核细胞没有核膜包被的细胞核。","a":"对","e":"原核细胞只有拟核，无核膜包被的细胞核。","kp":"","kpId":"bc01_s0_54"}],"fill":[{"id":"bc01_exam_fill1","modI":0,"q":"生物大分子通常指相对分子质量大于______的多聚体。","a":"5000","e":"教材常用5000作为生物大分子的界限。","kp":"","kpId":"bc01_s0_14"},{"id":"bc01_exam_fill2","modI":0,"q":"蛋白质的基本构件是______。","a":"氨基酸","e":"蛋白质由氨基酸聚合而成。","kp":"","kpId":"bc01_s0_0"},{"id":"bc01_exam_fill3","modI":0,"q":"核酸的基本构件是______。","a":"核苷酸","e":"核酸由核苷酸聚合而成。","kp":"","kpId":"bc01_s0_0"},{"id":"bc01_exam_fill4","modI":0,"q":"多糖的基本构件是______。","a":"单糖","e":"多糖由单糖聚合而成。","kp":"","kpId":"bc01_s0_0"},{"id":"bc01_exam_fill5","modI":0,"q":"水的高热容主要与分子间______有关。","a":"氢键","e":"水分子间形成大量氢键，吸收热量。","kp":"","kpId":"bc01_s0_38"}],"term":[{"id":"bc01_exam_term1","modI":0,"term":"生命元素","def":"组成生物体所必需的化学元素，分为大量元素和微量元素。","kps":"大量/微量元素+必需","kp":"","kpId":"bc01_s0_14"},{"id":"bc01_exam_term2","modI":0,"term":"生物大分子","def":"由单体聚合而成、相对分子质量通常大于5000的高分子，如蛋白质、核酸、多糖。","kps":"单体聚合+M>5000","kp":"","kpId":"bc01_s0_14"},{"id":"bc01_exam_term3","modI":0,"term":"构型","def":"分子中原子或基团的空间排列方式，改变构型需要断裂共价键，如D/L、顺反异构。","kps":"空间排列+需断键","kp":"","kpId":"bc01_s0_26"},{"id":"bc01_exam_term4","modI":0,"term":"构象","def":"分子通过单键旋转产生的不同空间形态，不涉及共价键断裂，如α螺旋、β折叠。","kps":"单键旋转+不断键","kp":"","kpId":"bc01_s0_26"},{"id":"bc01_exam_term5","modI":0,"term":"对映体","def":"互为镜像但不能重合的一对立体异构体，旋光方向相反，生物活性可不同。","kps":"镜像+不能重合+旋光相反","kp":"","kpId":"bc01_s0_26"}],"short":[{"id":"bc01_short_1","modI":0,"q":"生物化学研究什么？它作为一门学科是怎样发展起来的？它与分子生物学有什么关系？","a":"(1) 生物化学研究生命属性的化学本质，包括生物分子的结构与功能、物质代谢与调节、遗传信息传递与表达等。\n(2) 现代生物化学大体经历三个阶段：静态/叙述生物化学（1770—1900，研究组成、分离、结构）→ 动态生物化学（1900—1950，研究代谢、酶、能量）→ 分子生物化学（1950年以后，研究大分子结构与分子机制）。\n(3) 分子生物学是生物化学发展的新阶段，研究DNA、RNA、蛋白质等生物大分子及其相互关系。","kps":"研究内容1分；三阶段各1分；与分子生物学关系1分","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"先答定义，再按“静态—动态—分子”三阶段，最后说二者关系；不要只写年份。","kpId":"bc01_s0_2"},{"id":"bc01_short_2","modI":0,"q":"进化过程中生命元素是怎样被选择的？硅和碳同为IVA族、都能形成4个单键，为什么硅没有成为生命骨架？","a":"(1) 生命元素的选择与环境中原料的可得性有关，也取决于元素及其化合物对生命过程特殊作用的适合性。\n(2) 碳能形成稳定的C—C单键、双键和三键，可构成链状、分支和环状骨架；CO₂溶于水，有利于碳循环。\n(3) 硅原子较大，Si—Si键比C—C弱，Si的多聚物遇水不稳定，SiO₂难溶于水，不利于在需氧环境中循环，因此硅只以痕量存在。","kps":"元素选择两个原因；C与Si比较：成键、稳定性、溶解性、循环","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"答“选择原因+碳的优势+硅的局限”三点；不要只说“碳是生命元素”。","kpId":"bc01_s0_14"},{"id":"bc01_short_3","modI":0,"q":"原始生物分子有立体异构体时，为什么生物几乎只利用一种异构体（如L-氨基酸、D-单糖）？","a":"现有观点认为：酶对底物具有立体专一性。生命起源后，具有选择性的酶和蛋白质逐步进化；代谢反应几乎都由酶催化，酶只与特定构型的底物结合，因此生物体优先利用一种对映体。","kps":"关键：酶对底物的立体专一性；不是化学合成偏倚","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"关键词是“酶促反应的立体专一性”，不是“另一种不存在”。","kpId":"bc01_s0_26"},{"id":"bc01_short_4","modI":0,"q":"苯丙胺（benzedrine）是消旋体，右旋苯丙胺（dexedrine）是单一活性对映体。为什么达到同样效应，消旋体所需剂量约为右旋体的2倍？","a":"该药物含一个手性碳，有一对对映体。右旋体（dexedrine）是主要活性形式；消旋体（benzedrine）中只有一半是右旋体，另一半左旋体活性很低，因此要达到同样生理效应，消旋体剂量约为右旋体的2倍。","kps":"手性碳；对映体；消旋体只有一半活性；剂量差2倍","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"核心：消旋体=等量对映体，只有一种有高活性。","kpId":"bc01_s0_26"},{"id":"bc01_short_5","modI":0,"q":"生物分子间和分子内的非共价相互作用有哪些？它们有什么区别？","a":"主要包括离子相互作用、氢键、范德华力和疏水作用。\n(1) 离子相互作用：带电基团间的静电吸引，受盐浓度和介电常数影响。\n(2) 氢键：H与N/O/F孤对电子作用，有方向性和饱和性。\n(3) 范德华力：瞬时偶极诱导，作用距离短，要求紧密堆积。\n(4) 疏水作用：非极性基团避水聚集，本质是水氢键网络的熵驱动。","kps":"四类非共价作用；每类特点：键能、方向性、饱和性、距离依赖","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"四类作用按“本质—特点—例子”比较；疏水作用不是一种吸引键。","kpId":"bc01_s0_38"},{"id":"bc01_short_6","modI":0,"q":"解释为什么水分子之间形成氢键会造成高比热容。","a":"水分子间形成大量氢键，构成动态氢键网络。加热时，一部分能量用于断裂氢键，而不是全部用于增加分子动能，因此使水温升高需要较多热量，表现为高比热容。氢键还具有协同性，使水的内聚力较大。","kps":"水的极性/氢键；氢键网络；吸热用于断氢键","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"关键词：氢键网络、断氢键耗能、温度升高慢。","kpId":"bc01_s0_38"},{"id":"bc01_short_7","modI":0,"q":"【计算】配制 0.4 mol/L NaOH 溶液 500 mL：(1) 需要多少克固体 NaOH？(2) 用质量浓度（g/L）和摩尔渗透压浓度表示该溶液。","a":"(1) n=cV=0.4 mol/L×0.500 L=0.20 mol；m=nM=0.20 mol×40 g/mol=8.0 g。\n(2) 质量浓度=8.0 g÷0.500 L=16 g/L；NaOH 完全解离为 Na⁺ 和 OH⁻，粒子总浓度=2×0.4=0.8 mol/L，故摩尔渗透压浓度=0.8 mol/L（即 0.8 osmol/L）。","kps":"n=cV；m=nM；质量浓度=m/V；渗透压浓度=粒子数×摩尔浓度","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"先算物质的量，再算质量；质量浓度用“溶质质量÷溶液体积”；渗透压浓度要乘粒子数。注意 500 mL=0.500 L。","kpId":"bc01_s0_0"},{"id":"bc01_short_8","modI":0,"q":"【计算】配制 0.5 mol/L 盐酸 2000 mL，需要量取浓盐酸（质量分数 37%，密度 1.20 g/mL）多少 mL？","a":"浓盐酸的物质的量浓度：c=1000ρw/M=1000×1.20×0.37÷36.5≈12.16 mol/L。\n所需 HCl：n=cV=0.5 mol/L×2.00 L=1.00 mol。\n所需浓盐酸体积：V=n/c=1.00 mol÷12.16 mol/L≈0.0822 L=82.2 mL。","kps":"c=1000ρw/M；稀释前后n不变；V=n/c","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"先把质量分数换算成物质的量浓度，再用稀释前后 HCl 物质的量不变。易错：把 2000 mL 当成 2000 L，或直接用 37% 当浓度。","kpId":"bc01_s0_53"},{"id":"bc01_short_9","modI":0,"q":"【计算】某弱酸溶液浓度为 0.02 mol/L，测得 pH=4.6：(1) 求[H⁺]；(2) 求该酸的 Ka 和 pKa。","a":"(1) pH=4.6，[H⁺]=10⁻⁴·⁶≈2.51×10⁻⁵ mol/L。\n(2) 弱酸 HA 解离：Ka≈[H⁺]²/(c−[H⁺])。\nKa≈(2.51×10⁻⁵)²/(0.02−2.51×10⁻⁵)≈3.15×10⁻⁸。\npKa=−lgKa≈7.50。","kps":"pH→[H+]；弱酸Ka≈[H+]^2/(c−[H+])；pKa=−lgKa","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"pH 是负对数，先换成浓度；弱酸解离用 Ka=[H⁺][A⁻]/[HA]，当[H⁺]远小于 c 时可近似 c−[H⁺]≈c。","kpId":"bc01_s0_53"},{"id":"bc01_short_10","modI":0,"q":"判断共轭酸碱对：H₂PO₄⁻/HPO₄²⁻、HCO₃⁻/CO₃²⁻、HCOOH/HCOO⁻中，哪个是共轭酸？","a":"共轭酸是给出质子后变成对应碱的物种，即每对中多一个H⁺的成员：\n(1) H₂PO₄⁻；(2) HCO₃⁻；(3) HCOOH。\n它们分别给出H⁺后形成HPO₄²⁻、CO₃²⁻、HCOO⁻。","kps":"共轭酸=得到质子后的形式；逐对判断","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"先找“多一个H⁺”的物种；共轭酸/共轭碱只差一个质子。","kpId":"bc01_s0_0"},{"id":"bc01_short_11","modI":0,"q":"【计算】溶液含 0.20 mol/L 醋酸钠和 0.60 mol/L 醋酸（pKa=4.76），求 pH。","a":"用 Henderson-Hasselbalch 方程：pH=pKa+lg([NaAc]/[HAc])。\npH=4.76+lg(0.20/0.60)=4.76+lg(1/3)=4.76−0.477≈4.28。","kps":"Henderson-Hasselbalch：pH=pKa+lg([A−]/[HA])","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"盐浓度在分子、酸浓度在分母；比值小于 1 时 pH 低于 pKa。不要代反。","kpId":"bc01_s0_53"},{"id":"bc01_short_12","modI":0,"q":"【计算】配制 0.2 mol/L、pH=5.0 的醋酸盐缓冲液，求所需醋酸和醋酸钠的浓度（醋酸 pKa=4.76）。","a":"设[NaAc]=x，[HAc]=y，则 x+y=0.2 mol/L。\n由 pH=pKa+lg(x/y)：5.0=4.76+lg(x/y)，lg(x/y)=0.24，x/y≈1.74。\n联立解得 x≈0.127 mol/L，y≈0.073 mol/L。\n即醋酸钠约 0.127 mol/L，醋酸约 0.073 mol/L。","kps":"pH=pKa+lg([盐]/[酸])；x+y=总浓度；解对数方程","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记","e":"先由 pH 与 pKa 求盐/酸比值，再用总浓度守恒解方程组。易错：把 x/y 写成 y/x，或忘记 x+y=0.2。","kpId":"bc01_s0_53"},{"id":"bc01_short_13","modI":0,"q":"计算醋酸钠和醋酸（pKa=4.76）的物质的量比为 (1) 2:1 和 (2) 1:10 的稀溶液的 pH。","a":"(1) pH=pKa+lg([NaAc]/[HAc])=4.76+lg2=4.76+0.30=5.06。\n(2) pH=4.76+lg(1/10)=4.76−1.00=3.76。","kps":"pH=pKa+lg(盐/酸)；2:1→lg2；1:10→lg(1/10)","freq":"原书课后题","prio":"A","req":"掌握","src":"朱圣庚第4版第1章笔记和课后习题详解","e":"盐/酸比例大于1时pH>pKa；比例小于1时pH<pKa。先取对数再加减。","kpId":"bc01_s0_53"},{"id":"bc01_short_14","modI":0,"q":"大肠杆菌短杆状，长约2 μm、直径0.8 μm（按圆柱体，V=πr²h）：(1) 首尾相连横跨直径0.5 mm针头需多少个？(2) 平均密度1.1×10³ g/L，一个细胞质量多少？(3) 被膜厚10 nm，占总体积百分之几？(4) 约15000个核糖体（直径18 nm），占细胞体积百分之几？(5) 葡萄糖约1 mmol/L，一个细胞含多少个葡萄糖分子？","a":"(1) 0.5 mm=500 μm；500÷2=250个。\n(2) V=πr²h=3.14×(0.4 μm)²×2 μm≈1.0048 μm³；m=ρV=1.1×10³ g/L×1.0048×10⁻¹⁵ L≈1×10⁻¹² g=1 pg。\n(3) 表面积=2πrh+2πr²≈6.0288 μm²；被膜体积≈6.0288×10×10⁻³ μm³≈0.06 μm³；占比≈6%。\n(4) 15000个核糖体体积≈0.0458 μm³；占比≈5%。\n(5) 1.0048 μm³=1.0048×10⁻¹⁵ L；n=1.0048×10⁻¹⁵×1×10⁻³=1.0048×10⁻¹⁸ mol；分子数≈6.04×10⁵个。","kps":"圆柱体V=πr²h；m=ρV；表面积；体积分数；n=cV；N=nNA","freq":"原书课后题","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记和课后习题详解","e":"单位统一是难点：μm→dm/L、nm→μm。先算体积，再算质量/表面积/分子数；百分数用“部分/总体积”。","kpId":"bc01_s0_54"},{"id":"bc01_short_15","modI":0,"q":"高速率细菌代谢要求高的表面-体积比：(1) 为什么表面-体积比影响代谢最高速率？(2) 计算淋病奈瑟球菌（直径0.5 μm）与球状阿米巴（直径150 μm）的表面-体积比，并比较。","a":"(1) 代谢速率受扩散限制，而扩散与表面积有关；表面-体积比越大，单位体积可交换的表面积越大，物质交换越快。\n(2) 球体 S/V=4πr²/(4/3πr³)=3/r。\n球菌：3/0.25 μm=12 μm⁻¹；阿米巴：3/75 μm=0.04 μm⁻¹。\n球菌的S/V约为阿米巴的12÷0.04=300倍。","kps":"球体S/V=3/r；r越小S/V越大；扩散限制","freq":"原书课后题","prio":"A","req":"理解","src":"朱圣庚第4版第1章笔记和课后习题详解","e":"直接用S/V=3/r，注意半径不是直径；比较倍数=12/0.04=300。","kpId":"bc01_s0_0"}],"calc":[],"toc":[{"title":"章封面与学习路线","pages":"2页","start":0,"end":2,"items":[{"title":"章封面/三条主线","start":0,"end":2}]},{"title":"一、生命属性与生物化学","pages":"PPT 3—8","start":2,"end":8,"items":[{"title":"（一）化学成分复杂而同一、结构错综而有序","pages":"PPT 4","start":3,"end":4},{"title":"（二）利用环境的能量和物质进行自我更新","pages":"PPT 5","start":4,"end":5},{"title":"（三）自我复制和自我装配是生命状态的精华","pages":"PPT 6","start":5,"end":6},{"title":"本节收束 + 难点拆解","pages":"PPT 7—8","start":6,"end":8}]},{"title":"二、生物化学与分子生物学","pages":"PPT 9—14","start":8,"end":14,"items":[{"title":"（一）现代生物化学的发展和分子生物学的兴起","pages":"PPT 10","start":9,"end":10},{"title":"（二）重要学术中心和学者","pages":"PPT 11","start":10,"end":11},{"title":"（三）发展中的我国生物化学","pages":"PPT 12","start":11,"end":12},{"title":"本节收束 + 难点拆解","pages":"PPT 13—14","start":12,"end":14}]},{"title":"三、生命物质的化学组成","pages":"PPT 15—26","start":14,"end":26,"items":[{"title":"（一）生命元素","pages":"PPT 16","start":15,"end":16},{"title":"（二）生物分子是碳的化合物（含原图1-1/1-2）","pages":"PPT 17—19","start":16,"end":19},{"title":"（三）生物小分子与代谢物（含原图1-3及局部放大）","pages":"PPT 20—23","start":19,"end":23},{"title":"（四）生物大分子及其单体亚基","pages":"PPT 24","start":23,"end":24},{"title":"本节收束 + 难点拆解","pages":"PPT 25—26","start":24,"end":26}]},{"title":"四、生物分子的三维结构","pages":"PPT 27—38","start":26,"end":38,"items":[{"title":"（一）生物分子的大小","pages":"PPT 28","start":27,"end":28},{"title":"（二）立体异构与构型（含原图1-4）","pages":"PPT 29—30","start":28,"end":30},{"title":"（三）构型的命名系统（含原图1-5）","pages":"PPT 31—32","start":30,"end":32},{"title":"（四）构象","pages":"PPT 33","start":32,"end":33},{"title":"（五）三维结构的分子模型（含原图1-9）","pages":"PPT 34—35","start":33,"end":35},{"title":"（六）生物分子间的相互作用是立体专一的","pages":"PPT 36","start":35,"end":36},{"title":"本节收束 + 难点拆解","pages":"PPT 37—38","start":36,"end":38}]},{"title":"五、生物系统中的非共价相互作用","pages":"PPT 39—46","start":38,"end":46,"items":[{"title":"（一）离子相互作用","pages":"PPT 40","start":39,"end":40},{"title":"（二）氢键","pages":"PPT 41","start":40,"end":41},{"title":"（三）范德华力","pages":"PPT 42","start":41,"end":42},{"title":"（四）疏水相互作用","pages":"PPT 43","start":42,"end":43},{"title":"（五）非共价作用对结构和功能是关键","pages":"PPT 44","start":43,"end":44},{"title":"本节收束 + 难点拆解","pages":"PPT 45—46","start":44,"end":46}]},{"title":"六、水和生命","pages":"PPT 47—54","start":46,"end":54,"items":[{"title":"（一）水的结构和性质（含原图1-12）","pages":"PPT 48—49","start":47,"end":49},{"title":"（二）水是生命的介质","pages":"PPT 50","start":49,"end":50},{"title":"（三）溶质影响水的依数性","pages":"PPT 51","start":50,"end":51},{"title":"（四）水、弱酸和弱碱的电离","pages":"PPT 52","start":51,"end":52},{"title":"本节收束 + 难点拆解","pages":"PPT 53—54","start":52,"end":54}]},{"title":"七、生命的基本单位——细胞","pages":"PPT 55—66","start":54,"end":66,"items":[{"title":"（一）生物三域（含原图1-15）","pages":"PPT 56—57","start":55,"end":57},{"title":"（二）细胞是结构和功能单位","pages":"PPT 58","start":57,"end":58},{"title":"（三）原核细胞代表——大肠杆菌（含原图1-16）","pages":"PPT 59—60","start":58,"end":60},{"title":"（四）真核细胞细胞器（含原图1-17）","pages":"PPT 61—62","start":60,"end":62},{"title":"本节收束 + 原图局部放大","pages":"PPT 63—65","start":62,"end":65},{"title":"难点拆解","pages":"PPT 66","start":65,"end":66}]},{"title":"八、生物分子的起源与进化","pages":"PPT 67—75","start":66,"end":75,"items":[{"title":"（一）最初的生物分子通过化学进化产生","pages":"PPT 68","start":67,"end":68},{"title":"（二）RNA可能是最早的基因和催化剂（含原图1-19）","pages":"PPT 69—70","start":68,"end":70},{"title":"（三）原始细胞的出现","pages":"PPT 71","start":70,"end":71},{"title":"（四）真核细胞从原核细胞进化而来（含原图1-20）","pages":"PPT 72—73","start":71,"end":73},{"title":"本节收束 + 难点拆解","pages":"PPT 74—75","start":73,"end":75}]},{"title":"总结、测试与附录","pages":"PPT 76—92","start":75,"end":92,"items":[{"title":"全章总结与高频考点","pages":"PPT 76","start":75,"end":76},{"title":"课堂自测与答案","pages":"PPT 77—78","start":76,"end":78},{"title":"计算题专项","pages":"PPT 79—81","start":78,"end":81},{"title":"原书课后题（15题）","pages":"PPT 82—92","start":81,"end":92}]},{"title":"反应式四步卡","pages":"PPT 93","start":92,"end":93,"items":[{"title":"图1-14 醋酸滴定/缓冲：pH怎么变？","pages":"PPT 93","start":92,"end":93}]},{"title":"卡点闭环（4页）","pages":"4页","start":93,"end":97,"items":[{"title":"诊断/例题/变式/错因四页一组","start":93,"end":97}]},{"title":"水/酸碱反应四步卡","pages":"PPT 94","start":97,"end":98,"items":[{"title":"水、弱酸弱碱电离与缓冲：H⁺去哪了？","pages":"PPT 94","start":97,"end":98}]}],"exerciseTitle":"生命的分子基础 · 网页题","exercises":[{"id":"bc01_ex1","no":1,"type":"简答","q":"生物化学研究什么？它作为一门学科是怎样发展起来的？它与分子生物学有什么关系？","kp":"研究内容1分；三阶段各1分；与分子生物学关系1分","analysis":"先答定义，再按“静态—动态—分子”三阶段，最后说二者关系；不要只写年份。","answer":"(1) 生物化学研究生命属性的化学本质，包括生物分子的结构与功能、物质代谢与调节、遗传信息传递与表达等。\n(2) 现代生物化学大体经历三个阶段：静态/叙述生物化学（1770—1900，研究组成、分离、结构）→ 动态生物化学（1900—1950，研究代谢、酶、能量）→ 分子生物化学（1950年以后，研究大分子结构与分子机制）。\n(3) 分子生物学是生物化学发展的新阶段，研究DNA、RNA、蛋白质等生物大分子及其相互关系。","slide":8,"slideTitle":"生物化学与分子生物学","kpId":"bc01_s0_8"},{"id":"bc01_ex2","no":2,"type":"简答","q":"进化过程中生命元素是怎样被选择的？硅和碳同为IVA族、都能形成4个单键，为什么硅没有成为生命骨架？","kp":"元素选择两个原因；C与Si比较：成键、稳定性、溶解性、循环","analysis":"答“选择原因+碳的优势+硅的局限”三点；不要只说“碳是生命元素”。","answer":"(1) 生命元素的选择与环境中原料的可得性有关，也取决于元素及其化合物对生命过程特殊作用的适合性。\n(2) 碳能形成稳定的C—C单键、双键和三键，可构成链状、分支和环状骨架；CO₂溶于水，有利于碳循环。\n(3) 硅原子较大，Si—Si键比C—C弱，Si的多聚物遇水不稳定，SiO₂难溶于水，不利于在需氧环境中循环，因此硅只以痕量存在。","slide":15,"slideTitle":"（一）生命元素","kpId":"bc01_s0_15"},{"id":"bc01_ex3","no":3,"type":"简答","q":"原始生物分子有立体异构体时，为什么生物几乎只利用一种异构体（如L-氨基酸、D-单糖）？","kp":"关键：酶对底物的立体专一性；不是化学合成偏倚","analysis":"关键词是“酶促反应的立体专一性”，不是“另一种不存在”。","answer":"现有观点认为：酶对底物具有立体专一性。生命起源后，具有选择性的酶和蛋白质逐步进化；代谢反应几乎都由酶催化，酶只与特定构型的底物结合，因此生物体优先利用一种对映体。","slide":28,"slideTitle":"（二）立体异构与构型","kpId":"bc01_s0_28"},{"id":"bc01_ex4","no":4,"type":"简答","q":"生物分子间和分子内的非共价相互作用有哪些？它们有什么区别？","kp":"四类非共价作用；每类特点：键能、方向性、饱和性、距离依赖","analysis":"四类作用按“本质—特点—例子”比较；疏水作用不是一种吸引键。","answer":"主要包括离子相互作用、氢键、范德华力和疏水作用。\n(1) 离子相互作用：带电基团间的静电吸引，受盐浓度和介电常数影响。\n(2) 氢键：H与N/O/F孤对电子作用，有方向性和饱和性。\n(3) 范德华力：瞬时偶极诱导，作用距离短，要求紧密堆积。\n(4) 疏水作用：非极性基团避水聚集，本质是水氢键网络的熵驱动。","slide":38,"slideTitle":"生物系统中的非共价相互作用","kpId":"bc01_s0_38"},{"id":"bc01_ex5","no":5,"type":"简答","q":"解释为什么水分子之间形成氢键会造成高比热容。","kp":"水的极性/氢键；氢键网络；吸热用于断氢键","analysis":"关键词：氢键网络、断氢键耗能、温度升高慢。","answer":"水分子间形成大量氢键，构成动态氢键网络。加热时，一部分能量用于断裂氢键，而不是全部用于增加分子动能，因此使水温升高需要较多热量，表现为高比热容。氢键还具有协同性，使水的内聚力较大。","slide":47,"slideTitle":"（一）水的结构和性质","kpId":"bc01_s0_47"},{"id":"bc01_ex6","no":6,"type":"计算","q":"【计算】配制 0.4 mol/L NaOH 溶液 500 mL：(1) 需要多少克固体 NaOH？(2) 用质量浓度（g/L）和摩尔渗透压浓度表示该溶液。","kp":"n=cV；m=nM；质量浓度=m/V；渗透压浓度=粒子数×摩尔浓度","analysis":"先算物质的量，再算质量；质量浓度用“溶质质量÷溶液体积”；渗透压浓度要乘粒子数。注意 500 mL=0.500 L。","answer":"(1) n=cV=0.4 mol/L×0.500 L=0.20 mol；m=nM=0.20 mol×40 g/mol=8.0 g。\n(2) 质量浓度=8.0 g÷0.500 L=16 g/L；NaOH 完全解离为 Na⁺ 和 OH⁻，粒子总浓度=2×0.4=0.8 mol/L，故摩尔渗透压浓度=0.8 mol/L（即 0.8 osmol/L）。","slide":78,"slideTitle":"计算专项（一）：溶液配制与稀释","kpId":"bc01_s0_78"},{"id":"bc01_ex7","no":7,"type":"计算","q":"【计算】配制 0.5 mol/L 盐酸 2000 mL，需要量取浓盐酸（质量分数 37%，密度 1.20 g/mL）多少 mL？","kp":"c=1000ρw/M；稀释前后n不变；V=n/c","analysis":"先把质量分数换算成物质的量浓度，再用稀释前后 HCl 物质的量不变。易错：把 2000 mL 当成 2000 L，或直接用 37% 当浓度。","answer":"浓盐酸的物质的量浓度：c=1000ρw/M=1000×1.20×0.37÷36.5≈12.16 mol/L。\n所需 HCl：n=cV=0.5 mol/L×2.00 L=1.00 mol。\n所需浓盐酸体积：V=n/c=1.00 mol÷12.16 mol/L≈0.0822 L=82.2 mL。","slide":78,"slideTitle":"计算专项（一）：溶液配制与稀释","kpId":"bc01_s0_78"},{"id":"bc01_ex8","no":8,"type":"计算","q":"【计算】某弱酸溶液浓度为 0.02 mol/L，测得 pH=4.6：(1) 求[H⁺]；(2) 求该酸的 Ka 和 pKa。","kp":"pH→[H+]；弱酸Ka≈[H+]^2/(c−[H+])；pKa=−lgKa","analysis":"pH 是负对数，先换成浓度；弱酸解离用 Ka=[H⁺][A⁻]/[HA]，当[H⁺]远小于 c 时可近似 c−[H⁺]≈c。","answer":"(1) pH=4.6，[H⁺]=10⁻⁴·⁶≈2.51×10⁻⁵ mol/L。\n(2) 弱酸 HA 解离：Ka≈[H⁺]²/(c−[H⁺])。\nKa≈(2.51×10⁻⁵)²/(0.02−2.51×10⁻⁵)≈3.15×10⁻⁸。\npKa=−lgKa≈7.50。","slide":79,"slideTitle":"计算专项（二）：pH、Ka 与缓冲液","kpId":"bc01_s0_79"},{"id":"bc01_ex9","no":9,"type":"简答","q":"判断共轭酸碱对：H₂PO₄⁻/HPO₄²⁻、HCO₃⁻/CO₃²⁻、HCOOH/HCOO⁻中，哪个是共轭酸？","kp":"共轭酸=得到质子后的形式；逐对判断","analysis":"先找“多一个H⁺”的物种；共轭酸/共轭碱只差一个质子。","answer":"共轭酸是给出质子后变成对应碱的物种，即每对中多一个H⁺的成员：\n(1) H₂PO₄⁻；(2) HCO₃⁻；(3) HCOOH。\n它们分别给出H⁺后形成HPO₄²⁻、CO₃²⁻、HCOO⁻。","slide":51,"slideTitle":"（四）水、弱酸和弱碱的电离","kpId":"bc01_s0_51"},{"id":"bc01_ex10","no":10,"type":"计算","q":"【计算】溶液含 0.20 mol/L 醋酸钠和 0.60 mol/L 醋酸（pKa=4.76），求 pH。","kp":"Henderson-Hasselbalch：pH=pKa+lg([A−]/[HA])","analysis":"盐浓度在分子、酸浓度在分母；比值小于 1 时 pH 低于 pKa。不要代反。","answer":"用 Henderson-Hasselbalch 方程：pH=pKa+lg([NaAc]/[HAc])。\npH=4.76+lg(0.20/0.60)=4.76+lg(1/3)=4.76−0.477≈4.28。","slide":80,"slideTitle":"计算专项（三）：缓冲液配比","kpId":"bc01_s0_80"},{"id":"bc01_ex11","no":11,"type":"计算","q":"【计算】配制 0.2 mol/L、pH=5.0 的醋酸盐缓冲液，求所需醋酸和醋酸钠的浓度（醋酸 pKa=4.76）。","kp":"pH=pKa+lg([盐]/[酸])；x+y=总浓度；解对数方程","analysis":"先由 pH 与 pKa 求盐/酸比值，再用总浓度守恒解方程组。易错：把 x/y 写成 y/x，或忘记 x+y=0.2。","answer":"设[NaAc]=x，[HAc]=y，则 x+y=0.2 mol/L。\n由 pH=pKa+lg(x/y)：5.0=4.76+lg(x/y)，lg(x/y)=0.24，x/y≈1.74。\n联立解得 x≈0.127 mol/L，y≈0.073 mol/L。\n即醋酸钠约 0.127 mol/L，醋酸约 0.073 mol/L。","slide":80,"slideTitle":"计算专项（三）：缓冲液配比","kpId":"bc01_s0_80"},{"id":"bc01_ex12","no":12,"type":"计算","q":"高速率细菌代谢要求高的表面-体积比：(1) 为什么表面-体积比影响代谢最高速率？(2) 计算淋病奈瑟球菌（直径0.5 μm）与球状阿米巴（直径150 μm）的表面-体积比，并比较。","kp":"球体S/V=3/r；r越小S/V越大；扩散限制","analysis":"直接用S/V=3/r，注意半径不是直径；比较倍数=12/0.04=300。","answer":"(1) 代谢速率受扩散限制，而扩散与表面积有关；表面-体积比越大，单位体积可交换的表面积越大，物质交换越快。\n(2) 球体 S/V=4πr²/(4/3πr³)=3/r。\n球菌：3/0.25 μm=12 μm⁻¹；阿米巴：3/75 μm=0.04 μm⁻¹。\n球菌的S/V约为阿米巴的12÷0.04=300倍。","slide":58,"slideTitle":"（三）原核细胞的代表——大肠杆菌","kpId":"bc01_s0_58"}],"kpMap":{"bc01_s0_2":{"label":"生命属性/生化史","slide":2},"bc01_s0_14":{"label":"生命物质与官能团","slide":14},"bc01_s0_26":{"label":"构型/构象/立体化学","slide":26},"bc01_s0_38":{"label":"非共价相互作用","slide":38},"bc01_s0_53":{"label":"水/pH/缓冲","slide":53},"bc01_s0_54":{"label":"细胞/三域","slide":54},"bc01_s0_66":{"label":"起源与进化","slide":66},"bc01_s0_0":{"label":"总结/计算/反应式","slide":0}},"preview":{"main":"先看主线：原书版课件里的核心概念 + 计算专项；再做课后题/卡点闭环；原书页和反应式卡只查阅。","questions":["先看哪几块建立框架？","计算题放在哪一步练？","哪些页只查阅？"]}};